topicId":"poa-s3-lesson-09","requires":["poa-s3-lesson-08"]},{"topicId":"poa-s4-lesson-10","requires":["poa-s3-lesson-09"]},{"topicId":"poa-s4-lesson-11","requires":["poa-s4-lesson-10"]},{"topicId":"poa-s5-lesson-12","requires":["poa-s4-lesson-11"]},{"topicId":"poa-s5-lesson-13","requires":["poa-s5-lesson-12"]},{"topicId":"poa-s5-lesson-14","requires":["poa-s5-lesson-13"]},{"topicId":"poa-s6-lesson-15","requires":["poa-s5-lesson-14"]},{"topicId":"poa-s6-lesson-16","requires":["poa-s6-lesson-15"]},{"topicId":"poa-s6-lesson-17","requires":["poa-s6-lesson-16"]},{"topicId":"poa-s7-lesson-18","requires":["poa-s6-lesson-17"]},{"topicId":"poa-s7-lesson-19","requires":["poa-s7-lesson-18"]},{"topicId":"poa-s7-lesson-20","requires":["poa-s7-lesson-19"]},{"topicId":"poa-s8-lesson-21","requires":["poa-s7-lesson-20"]},{"topicId":"poa-s8-lesson-22","requires":["poa-s8-lesson-21"]},{"topicId":"poa-s8-lesson-23","requires":["poa-s8-lesson-22"]},{"topicId":"poa-s9-lesson-24","requires":["poa-s8-lesson-23"]},{"topicId":"poa-s9-lesson-25","requires":["poa-s9-lesson-24"]},{"topicId":"poa-s9-lesson-26","requires":["poa-s9-lesson-25"]},{"topicId":"poa-s10-lesson-27","requires":["poa-s9-lesson-26"]},{"topicId":"poa-s10-lesson-28","requires":["poa-s10-lesson-27"]},{"topicId":"poa-s10-lesson-29","requires":["poa-s10-lesson-28"]},{"topicId":"poa-s11-lesson-30","requires":["poa-s10-lesson-29"]},{"topicId":"poa-s11-lesson-31","requires":["poa-s11-lesson-30"]},{"topicId":"poa-s11-lesson-32","requires":["poa-s11-lesson-31"]},{"topicId":"poa-s11-lesson-33","requires":["poa-s11-lesson-32"]}]}'::jsonb,1)
