insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s1-lesson-01','poa-section-1','What accounting tells us','Accounting means identifying, recording, classifying, summarising and interpreting financial transactions. Bookkeeping is the recording part; accounting also explains what the records mean. A transaction is an event that changes the money, property, obligations or ownership interest of a business. Buying stock, selling goods and paying rent are transactions. An enquiry about prices is not yet a transaction.',0,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":7,"section":1,"objectiveCodes":["S1.1","S1.2"]},"lesson":{"introduction":"Accounting means identifying, recording, classifying, summarising and interpreting financial transactions. Bookkeeping is the recording part; accounting also explains what the records mean. A transaction is an event that changes the money, property, obligations or ownership interest of a business. Buying stock, selling goods and paying rent are transactions. An enquiry about prices is not yet a transaction.","objectives":["explain the concept and purposes of Accounting","identify the users of accounting information"],"sections":[{"title":"Understand the idea","paragraphs":["Think of a small shop in Montego Bay. Its owner needs to know whether sales cover costs, how much customers owe and whether enough cash will be available to pay suppliers. Records support planning, control, accountability and decisions. Profit measures performance over a period. A balance sheet shows financial position on one date. Neither replaces the other.","Internal users include owners and managers deciding prices, staffing and expansion. External users include lenders assessing repayment, suppliers considering credit, investors assessing returns, employees considering security, and government agencies checking required returns. Match the information to the decision: a lender needs cash and debt information, while a manager comparing products needs costs and margins.","Follow the difference between profit and cash with one event at a time. A shop sells goods costing $7,000 for $12,000 on credit. With no other items, profit is $5,000 even though no customer cash has arrived. When the customer later pays $12,000, bank rises and the debt disappears; the payment does not create another $12,000 of sales. This is why good records show sales, debts, costs and cash separately.","Before using a figure, ask three questions: what does it measure, which period or date does it cover, and what decision will it support? A year''s sales cannot be compared directly with a single day''s cash balance to decide whether the business is profitable. A manager investigating falling profit needs an income statement and supporting costs; a supplier concerned about next month''s payment needs short-term cash and liability information."]},{"title":"Worked example","paragraphs":["A shop receives $8,000 from customers but spends $6,000 on stock and $1,000 on rent. The cash movement is +$1,000. You cannot call this net profit without knowing how much stock was sold, any credit sales and unpaid expenses."]},{"title":"Common mistake","paragraphs":["Money received is not always revenue: an owner''s investment or bank loan also increases cash."]}],"keyPoints":["Bookkeeping records transactions; accounting also explains them.","Match the information to the user''s decision.","A credit sale can earn profit before the customer pays."],"summary":"Accounting turns transaction records into information people can use. Always distinguish profit, cash and the financial position of a business.","check":{"question":"A supplier is deciding whether to allow 30 days to pay. What information matters?","answer":"Liquidity, existing debts and payment history help the supplier assess whether the business can pay on time."},"flashcards":[{"front":"A supplier is deciding whether to allow 30 days to pay. What information matters?","back":"Liquidity, existing debts and payment history help the supplier assess whether the business can pay on time."},{"front":"What mistake should you avoid when studying what accounting tells us?","back":"Money received is not always revenue: an owner''s investment or bank loan also increases cash."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s1-lesson-02','poa-section-1','Careers, trust and ethical choices','Accounting work includes bookkeeping, payroll, financial accounting, management accounting, auditing, taxation and forensic investigation. A bookkeeper records transactions; a management accountant helps managers plan and control; an auditor examines evidence; a forensic accountant investigates suspected financial misconduct. Banks, insurers, businesses and entrepreneurs all use accounting skills. Digital systems also create roles in financial data analysis and systems control.',1,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":7,"section":1,"objectiveCodes":["S1.3","S1.4"]},"lesson":{"introduction":"Accounting work includes bookkeeping, payroll, financial accounting, management accounting, auditing, taxation and forensic investigation. A bookkeeper records transactions; a management accountant helps managers plan and control; an auditor examines evidence; a forensic accountant investigates suspected financial misconduct. Banks, insurers, businesses and entrepreneurs all use accounting skills. Digital systems also create roles in financial data analysis and systems control.","objectives":["describe traditional and emerging careers in the field of Accounting","discuss ethical issues in the field of Accounting."],"sections":[{"title":"Understand the idea","paragraphs":["Integrity means being honest, including when an error makes the business look better. Objectivity means resisting bias and conflicts of interest. Professional competence means keeping skills current and recognising limits. Confidentiality means protecting information except where authorised or required to disclose it. Professional behaviour means following relevant rules and avoiding conduct that discredits the profession.","If a manager asks you to hide an unpaid bill, keep the evidence, explain that the liability belongs in the records, and use the organisation''s reporting process. Do not change a record just to please someone. Deliberate falsification can cause bad lending decisions, loss of trust, disciplinary action and legal consequences. Ethical reasoning should explain the action, the principle affected and the likely harm.","Use a four-part answer for an ethics case. First identify the action, such as recording an invented sale. Next name the affected principle, such as integrity. Then explain the consequence: overstated revenue could mislead a lender. Finally give a practical response: retain the evidence, refuse to make a false entry, explain the correct treatment and follow an appropriate reporting route. Merely saying ''it is wrong'' does not show the accounting effect.","Good controls make honest work easier. The person who approves a purchase should, where staffing permits, be different from the person who pays it and reconciles the bank. A small business may need the owner to review invoices and reconciliations if full separation is impractical. Restrict payroll access, log changes and keep a recoverable backup. A password shared with everyone removes accountability even when a system records a username."]},{"title":"Worked example","paragraphs":["A payroll clerk sends employees'' salaries to a friend. Even if the amounts are correct, sharing confidential information without authority breaches confidentiality. Restrict access and report the disclosure through the proper process."]},{"title":"Common mistake","paragraphs":["An instruction from a senior employee does not make a false entry acceptable."]}],"keyPoints":["Integrity requires honest records, even when the truth is inconvenient.","Disclose conflicts of interest and protect confidential information.","Separate duties and keep evidence of approvals and changes."],"summary":"Reliable accounts depend on honest decisions as well as accurate arithmetic. Identify the ethical issue, explain its effect and choose a practical response.","check":{"question":"Which ethical principle is threatened when an accountant favours a supplier owned by a relative?","answer":"Objectivity: the personal connection creates a conflict that should be disclosed and managed."},"flashcards":[{"front":"Which ethical principle is threatened when an accountant favours a supplier owned by a relative?","back":"Objectivity: the personal connection creates a conflict that should be disclosed and managed."},{"front":"What mistake should you avoid when studying careers, trust and ethical choices?","back":"An instruction from a senior employee does not make a false entry acceptable."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-03','poa-section-2','The rules and the accounting cycle','The separate entity concept treats the business''s records separately from the owner''s personal affairs. A sole trader''s personal groceries are drawings, not a business expense. Accruals recognise income when earned and expenses when incurred, rather than simply when money changes hands. Matching puts expenses against the revenue of the appropriate period.',2,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":9,"section":2,"objectiveCodes":["S2.1","S2.2"]},"lesson":{"introduction":"The separate entity concept treats the business''s records separately from the owner''s personal affairs. A sole trader''s personal groceries are drawings, not a business expense. Accruals recognise income when earned and expenses when incurred, rather than simply when money changes hands. Matching puts expenses against the revenue of the appropriate period.","objectives":["outline the concepts and conventions that guide the accounting process","describe the accounting cycle"],"sections":[{"title":"Understand the idea","paragraphs":["Prudence means exercising care under uncertainty: do not overstate assets or income or understate liabilities or expenses. It does not mean deliberately understating profit. Consistency means using comparable methods from period to period; a justified change must be explained. These ideas make records more useful than a list of cash movements alone.","Follow the accounting cycle: transaction → source document → book of original entry → ledger → trial balance → adjustments → financial statements → closing entries. A receipt provides evidence; a day book groups similar transactions; ledger accounts collect changes for each account; the trial balance checks debit and credit totals. Adjustments bring the records into the correct period before statements are prepared.","See the cycle as a route that evidence follows. A credit purchase begins with a supplier invoice, enters the purchases day book, is posted to purchases and the supplier account, and contributes to trial-balance balances. At year end, unsold stock and unpaid costs are considered before profit is calculated. The final statements summarise those records. Closing income and expense accounts prepares them for the next period; opening assets and liabilities continue.","Check a concept by asking which period bears the cost and whose activity it is. The owner''s $4,000 holiday paid from business bank is drawings under the separate entity concept. A $1,200 December utility bill unpaid at year end is an expense and an accrued liability under accruals and matching. An estimated doubtful-debt allowance reflects care about receivables that may not be recovered. Applying the same suitable depreciation method across periods supports consistency."]},{"title":"Worked example","paragraphs":["December electricity of $900 is paid in January. December''s expense is still $900: debit electricity expense and credit accrued electricity $900. January payment clears the liability instead of creating December''s expense again."]},{"title":"Common mistake","paragraphs":["A balanced trial balance checks arithmetic agreement; it does not prove every transaction is correct."]}],"keyPoints":["Keep the owner''s personal transactions separate from business expenses.","Record income when earned and expenses in the period they relate to.","Equal trial-balance totals do not prove that every entry is correct."],"summary":"Follow each transaction from its source document through the books, ledgers and trial balance to the financial statements. Apply the accounting concepts at every stage.","check":{"question":"The owner pays a personal phone bill from business cash. What is the entry?","answer":"Debit drawings and credit cash. The separate entity concept keeps the personal cost out of business expenses."},"flashcards":[{"front":"The owner pays a personal phone bill from business cash. What is the entry?","back":"Debit drawings and credit cash. The separate entity concept keeps the personal cost out of business expenses."},{"front":"What mistake should you avoid when studying the rules and the accounting cycle?","back":"A balanced trial balance checks arithmetic agreement; it does not prove every transaction is correct."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-04','poa-section-2','Business types, statements and technology','A sole trader has one owner and a capital account. A partnership has partners whose agreement governs profit sharing and capital. A company has shareholders and separate legal identity. A cooperative serves members through joint ownership and democratic participation. A non-profit organisation aims to provide services rather than distribute business profits to owners. The organisation''s purpose changes the statements and equity labels it uses.',3,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":9,"section":2,"objectiveCodes":["S2.3","S2.4","S2.5"]},"lesson":{"introduction":"A sole trader has one owner and a capital account. A partnership has partners whose agreement governs profit sharing and capital. A company has shareholders and separate legal identity. A cooperative serves members through joint ownership and democratic participation. A non-profit organisation aims to provide services rather than distribute business profits to owners. The organisation''s purpose changes the statements and equity labels it uses.","objectives":["appraise the accounting features of various types of business organisations","identify the main financial statements prepared by various business organisations;","assess the role and impact of technology on the accounting process"],"sections":[{"title":"Understand the idea","paragraphs":["An income statement reports revenue, expenses and profit over a period. A balance sheet reports assets, liabilities and equity on a date. A cash flow statement explains movements in cash. A non-profit income and expenditure account measures the period''s surplus or deficit on an accrual basis; a receipts and payments account lists cash movements. Do not confuse those two accounts.","Software can process payroll, inventory, receivables and payables quickly, generate reports and reduce repeated arithmetic. Spreadsheets allow flexible calculations; accounting packages link records and keep audit trails. Automation still depends on correct source data, suitable account codes and controlled access. Use backups, permissions, reconciliations and review. A wrong formula or duplicated invoice can spread errors through many reports, while outages, security failures and training costs also matter.","Match the report to its owner labels. A sole trader''s statement ends with capital; a partnership distinguishes each partner''s interest; a company distinguishes share capital and reserves; a cooperative shows member funds and the distribution of surplus using its rules. A club''s receipts and payments account explains cash, while its accumulated fund represents net assets. The basic relationship between assets, liabilities and the owners'' or members'' interest still applies.","A useful software answer names the task and the control. For receivables, software can generate customer statements and an overdue-debt list; staff must still check opening balances and match receipts correctly. For inventory, it can update quantities after each receipt or issue; staff must still compare records with a physical count. For payroll, it can reuse approved employee rates; access to those rates and bank details needs protection. Faster processing makes checking the inputs more important."]},{"title":"Worked example","paragraphs":["A credit union records member shares and loans; a school club records subscriptions and cash spent on events. Both need reliable records, but the club''s receipts and payments account is not a company''s profit appropriation account."]},{"title":"Common mistake","paragraphs":["Software does not decide whether a personal purchase belongs in business expenses."]}],"keyPoints":["An income statement reports performance over a period.","A balance sheet reports assets, liabilities and equity on a date.","Cash flow and profit can move differently."],"summary":"Choose statements that suit the organisation and the question being answered. Software makes recording faster, but the person entering the data still has to classify it correctly.","check":{"question":"Why might a business earn profit but have little cash?","answer":"Customers may not have paid credit sales, or cash may have been spent on equipment, inventory, drawings or loan repayments."},"flashcards":[{"front":"Why might a business earn profit but have little cash?","back":"Customers may not have paid credit sales, or cash may have been spent on equipment, inventory, drawings or loan repayments."},{"front":"What mistake should you avoid when studying business types, statements and technology?","back":"Software does not decide whether a personal purchase belongs in business expenses."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-05','poa-section-2','Assets, liabilities and the balance sheet','An asset is a resource controlled by the business from which future benefits are expected. A liability is an obligation owed to others. Capital is the owner''s residual interest: assets minus liabilities. The accounting equation is assets = capital + liabilities. Every recorded transaction must preserve this equality, although several items may change at once.',4,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":10,"section":2,"objectiveCodes":["S2.6","S2.7","S2.8","S2.9","S2.10"]},"lesson":{"introduction":"An asset is a resource controlled by the business from which future benefits are expected. A liability is an obligation owed to others. Capital is the owner''s residual interest: assets minus liabilities. The accounting equation is assets = capital + liabilities. Every recorded transaction must preserve this equality, although several items may change at once.","objectives":["explain the concept of a Balance Sheet and the balance sheet equation","identify the components of a Balance Sheet","give examples of different types of assets and liabilities","construct Balance Sheets","determine which items in a Balance Sheet will change as a result of various transactions."],"sections":[{"title":"Understand the idea","paragraphs":["Non-current assets such as equipment are held for continuing use. Current assets such as inventory, trade receivables, bank and cash are expected to turn into cash, be sold or be used within the operating cycle or relevant short-term period. Current liabilities such as trade payables and a short-term overdraft fall due soon. A long-term loan is a non-current liability, but the portion due soon is current when classification is required.","Head a balance sheet with the business name, statement title and date. In vertical form list non-current assets, then current assets, deduct current liabilities to find working capital, add net non-current assets and deduct non-current liabilities to arrive at net assets. Reconcile net assets to closing capital. In an order of permanence, longer-held assets come first; in liquidity order, the easiest to convert to cash come first. Label the basis clearly.","Build a complete vertical statement in stages. Equipment cost $60,000 less accumulated depreciation $12,000 gives non-current assets $48,000. Inventory $12,000, receivables $8,000 and bank $4,000 give current assets $24,000. Deduct current payables $10,000 to obtain working capital $14,000. Add $48,000 to obtain $62,000, then deduct a long-term loan $12,000: net assets are $50,000. The financed-by section must also total $50,000.","Test the equation after a change rather than memorising a direction. Buying $3,000 of inventory on credit adds $3,000 to inventory and $3,000 to payables; capital is unchanged. Paying $2,000 of that debt reduces bank and payables by $2,000 each. Introducing $5,000 of the owner''s savings increases bank and capital by $5,000 each. Paying a $500 business expense reduces bank and, through lower profit, reduces capital by $500."]},{"title":"Worked example","paragraphs":["Keisha invests $40,000 cash and borrows $10,000. Assets $50,000 = capital $40,000 + liabilities $10,000. Buying a $12,000 refrigerator for cash leaves total assets $50,000: equipment rises $12,000 and cash falls $12,000. Buying $3,000 inventory on credit increases assets and liabilities by $3,000 each."]},{"title":"Common mistake","paragraphs":["A loan is a liability, not income. Buying an asset for cash does not necessarily change total assets."]}],"keyPoints":["Assets = capital + liabilities.","Capital = assets − liabilities.","Buying an asset for cash changes the mix of assets, not necessarily their total."],"summary":"The accounting equation connects what a business owns, what it owes and the owner''s interest. Check the effect of each transaction on both sides.","check":{"question":"Assets are $96,000 and liabilities are $31,000. Find capital.","answer":"Capital = $96,000 − $31,000 = $65,000."},"flashcards":[{"front":"Assets are $96,000 and liabilities are $31,000. Find capital.","back":"Capital = $96,000 − $31,000 = $65,000."},{"front":"What mistake should you avoid when studying assets, liabilities and the balance sheet?","back":"A loan is a liability, not income. Buying an asset for cash does not necessarily change total assets."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-06','poa-section-3','From source documents to day books','Books of original entry organise transactions before posting to ledger accounts. The sales day book records credit sales of goods normally traded. The purchases day book records credit purchases of trading goods. Returns inwards records customer returns; returns outwards records returns to suppliers. The cash book records cash and bank receipts and payments; petty cash records small payments. The general journal records entries that do not belong in those specialised books.',5,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":12,"section":3,"objectiveCodes":["S3.1","S3.2","S3.3"]},"lesson":{"introduction":"Books of original entry organise transactions before posting to ledger accounts. The sales day book records credit sales of goods normally traded. The purchases day book records credit purchases of trading goods. Returns inwards records customer returns; returns outwards records returns to suppliers. The cash book records cash and bank receipts and payments; petty cash records small payments. The general journal records entries that do not belong in those specialised books.","objectives":["explain the uses of books of original entry","distinguish between cash and credit transactions","identify source documents related to books of original entry;"],"sections":[{"title":"Understand the idea","paragraphs":["A cash transaction is settled immediately; a credit transaction creates an amount to be paid later. A debit card normally moves bank funds immediately. A credit card payment creates a settlement relationship with the card provider or bank; read the question''s facts rather than assuming it means a sale on trade credit to the customer. Cheques and electronic transfers belong in the bank column, not physical cash.","An invoice states goods, quantities, prices, discounts, date and parties. A credit note reduces the amount owed, commonly after returns. A debit note can notify or request an adjustment; check who issued it and what happened. A receipt acknowledges payment and a petty cash voucher supports a small payment. Always work from the business whose books you are preparing: its purchase invoice is the seller''s sales invoice.","Use the same short decision path for every document: is this business buying or selling; is it trading goods or another item; is payment immediate or later; is this a new transaction, return or settlement? A supplier''s statement is a summary for checking the supplier account, not a new purchase invoice. Recording both the invoices and the full statement as new purchases would duplicate the debts.","A returned-goods example keeps the viewpoint clear. Coral Stores sold a customer goods on credit for $2,000. The customer returns $300 of those goods and Coral accepts them. Coral issues a credit note and records $300 in returns inwards, reducing the customer''s debt to $1,700. In the customer''s books the same document supports returns outwards. The name of the book depends on whose records are being prepared."]},{"title":"Worked example","paragraphs":["A furniture retailer buys ten chairs for resale on 30-day credit: purchases day book. It buys an office computer on credit: general journal, because the computer is a non-current asset. A customer pays an old debt by transfer: cash book, bank receipts."]},{"title":"Common mistake","paragraphs":["The purchases day book is not a list of everything bought. It normally contains credit purchases of trading goods."]}],"keyPoints":["Credit purchases of resale goods enter the purchases day book.","Cash and bank transactions enter the cash book.","A credit note reduces the amount a customer owes after an accepted return."],"summary":"Start with the evidence, then choose the correct book of original entry. The transaction''s nature matters more than the fact that money or goods changed hands.","check":{"question":"Which document would a seller issue when accepting returned goods?","answer":"A credit note, reducing the customer''s amount owed."},"flashcards":[{"front":"Which document would a seller issue when accepting returned goods?","back":"A credit note, reducing the customer''s amount owed."},{"front":"What mistake should you avoid when studying from source documents to day books?","back":"The purchases day book is not a list of everything bought. It normally contains credit purchases of trading goods."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-07','poa-section-3','Prepare documents, record and post totals','To prepare an invoice, enter a unique reference, date, seller, buyer, descriptions, quantities and unit prices. Multiply quantities by prices, deduct trade discounts and show the total due. Add only taxes or charges specified in the question. A credit note should identify the original invoice and the returned or overcharged items. A receipt should identify the payer, date, payment method and amount.',6,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.4","S3.5","S3.6","S3.11"]},"lesson":{"introduction":"To prepare an invoice, enter a unique reference, date, seller, buyer, descriptions, quantities and unit prices. Multiply quantities by prices, deduct trade discounts and show the total due. Add only taxes or charges specified in the question. A credit note should identify the original invoice and the returned or overcharged items. A receipt should identify the payer, date, payment method and amount.","objectives":["prepare source documents for use in transaction descriptions","translate source documents into transaction descriptions","use source documents to make entries into books of original entry","indicate treatment of totals from books of original entry."],"sections":[{"title":"Understand the idea","paragraphs":["Translate the document into a short transaction: who bought or sold, what changed, whether settlement was immediate, and the amount after trade discount. Enter it once in the correct original-entry book. Keep the date, document reference, other party and net amount so the entry can be traced. Do not record the same sale again when the customer later pays it; the later event settles a receivable.","Post sales day book totals by debiting the relevant receivables control or individual customers and crediting sales in the appropriate ledger system. Purchases totals debit purchases and credit payables. Sales returns debit returns inwards and credit receivables; purchases returns debit payables and credit returns outwards. Individual customer and supplier postings keep personal accounts accurate. A control-account system requires corresponding subsidiary records; control totals are not extra customer debts.","A day-book total and the personal postings have different jobs. Suppose two credit invoices are $3,000 to Ana and $2,000 to Ben. In a system using receivables control, debit control $5,000 and credit sales $5,000 in the general ledger; also debit Ana $3,000 and Ben $2,000 in the subsidiary sales ledger. Do not add the subsidiary balances to the control balance as though the business is owed $10,000. They are two views of the same $5,000.","Keep a document trail that another person can follow: invoice number in the day book, day-book reference in the ledger and ledger references back to the original entry. When an invoice total is changed by a credit note, preserve both references rather than erasing the original transaction. For a general-journal entry, show the debit account first, indent or otherwise identify the credit account, write equal amounts, and add a short narration explaining the event."]},{"title":"Worked example","paragraphs":["Invoice 014: 8 bags at $2,500 = $20,000, less 10% trade discount $2,000, net $18,000. For the buyer''s credit purchase of resale goods: debit purchases $18,000, credit supplier $18,000. Returning two bags at the same net price produces a $4,500 credit note."]},{"title":"Common mistake","paragraphs":["Record the net invoice amount. Do not post the trade discount to a separate discount account."]}],"keyPoints":["Quantity × unit price gives the amount before discounts.","Deduct trade discount before recording an invoice.","Use document numbers and dates to trace postings back to evidence."],"summary":"Prepare documents carefully, record their net amounts and post the totals to the general ledger. Keep individual customer and supplier records consistent with the totals.","check":{"question":"A sales day book totals $47,000. State the general ledger effect.","answer":"Debit trade receivables/control $47,000 and credit sales $47,000; update individual customer records as required."},"flashcards":[{"front":"A sales day book totals $47,000. State the general ledger effect.","back":"Debit trade receivables/control $47,000 and credit sales $47,000; update individual customer records as required."},{"front":"What mistake should you avoid when studying prepare documents, record and post totals?","back":"Record the net invoice amount. Do not post the trade discount to a separate discount account."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-08','poa-section-3','Trade discounts and settlement discounts','A trade discount reduces a list price before the transaction is recorded. It can reward bulk buying or trade relationships. A cash or settlement discount rewards payment within stated terms. Record the trade discount first; calculate any settlement discount on the remaining qualifying debt, following the question''s terms.',7,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.7","S3.8"]},"lesson":{"introduction":"A trade discount reduces a list price before the transaction is recorded. It can reward bulk buying or trade relationships. A cash or settlement discount rewards payment within stated terms. Record the trade discount first; calculate any settlement discount on the remaining qualifying debt, following the question''s terms.","objectives":["distinguish between trade and cash discounts","distinguish between discounts allowed and discounts received"],"sections":[{"title":"Understand the idea","paragraphs":["From the seller''s view, discount allowed is the reduction given to a customer for prompt settlement. It is normally a debit expense in these examination accounts. From the buyer''s view, discount received reduces what is paid to a supplier and is a credit income item. The words allowed and received describe the business''s perspective, not the movement of cash alone.","In a three-column cash book, discount allowed appears on the receipts side beside the amount received; discount received appears on the payments side beside the amount paid. The bank or cash amount plus settlement discount clears the whole debt. Discount columns are totalled and posted to the appropriate ledger accounts. They are not balanced like cash and bank columns.","Returns can change the settlement-discount base. A customer owes $8,000 after trade discount, returns goods with a net invoice value of $2,000, and qualifies for 5% discount on the remaining debt. The remaining debt is $6,000; discount allowed is $300; bank receives $5,700. Debit bank $5,700 and discount allowed $300, then credit the customer $6,000. Do not calculate the discount on goods that have already been returned.","Check the three amounts whenever a debt is settled: money transferred + settlement discount = debt cleared. For a supplier debt of $4,500 with 2% discount, the discount received is $90 and payment is $4,410. The supplier account is debited $4,500, not only $4,410, because the whole debt is cleared. State whether the discount was allowed or received from the business''s point of view."]},{"title":"Worked example","paragraphs":["List price $10,000 less 20% trade discount gives an $8,000 invoice. A further 5% settlement discount is $400, so the customer pays $7,600. Seller: debit bank $7,600, debit discount allowed $400, credit customer $8,000. Buyer: debit supplier $8,000, credit bank $7,600, credit discount received $400."]},{"title":"Common mistake","paragraphs":["20% followed by 5% is not a 25% discount: each percentage has a different base."]}],"keyPoints":["Apply successive percentages to the correct changing base.","The seller records settlement discount as discount allowed.","The buyer records settlement discount as discount received."],"summary":"Trade discount changes the invoice price. Settlement discount reduces the amount paid when the customer meets the payment terms.","check":{"question":"A customer owes $6,000 and receives 2% discount for paying now. How much enters bank?","answer":"$5,880; the $120 discount allowed and $5,880 receipt together clear $6,000."},"flashcards":[{"front":"A customer owes $6,000 and receives 2% discount for paying now. How much enters bank?","back":"$5,880; the $120 discount allowed and $5,880 receipt together clear $6,000."},{"front":"What mistake should you avoid when studying trade discounts and settlement discounts?","back":"20% followed by 5% is not a 25% discount: each percentage has a different base."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-09','poa-section-3','Cash books, contra entries and petty cash','The debit side of the cash book records money coming in; the credit side records money going out. A two-column book has cash and bank; a three-column book adds discount. The cash book is both a book of original entry and a ledger account, so do not create a duplicate bank ledger posting. Cash cannot have a credit balance because physical cash cannot be below zero; bank can show an overdraft.',8,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.9","S3.10"]},"lesson":{"introduction":"The debit side of the cash book records money coming in; the credit side records money going out. A two-column book has cash and bank; a three-column book adds discount. The cash book is both a book of original entry and a ledger account, so do not create a duplicate bank ledger posting. Cash cannot have a credit balance because physical cash cannot be below zero; bank can show an overdraft.","objectives":["balance cash books","interpret the balances of the cash books"],"sections":[{"title":"Understand the idea","paragraphs":["A contra entry transfers money between business cash and business bank. For cash lodged, debit bank and credit cash; for a withdrawal for office cash, debit cash and credit bank. Mark both entries C. A withdrawal for the owner''s private use is drawings, not a contra transfer. Balance each cash or bank column separately: put balance carried down on the smaller side to equalise totals, then bring the balance down on the opposite side for the next period.","Under the imprest system, petty cash starts with a fixed float. Record each supported payment in the total and the correct analysis column, such as postage or travel. Reimbursement restores the agreed float. The reimbursement equals supported expenditure if the float is unchanged and there are no shortages. Count the cash and reconcile it to the record; a voucher is evidence of expenditure, not extra cash.","Work through a complete cash-book balance. Start with cash $1,000 and bank $5,000. Receive cash sales $2,000; lodge cash $1,500; receive a customer''s cheque $3,000 with discount allowed $100; pay a supplier by cheque $1,400 with discount received $100; pay cash expenses $400. Closing cash is 1,000 + 2,000 − 1,500 − 400 = $1,100. Closing bank is 5,000 + 1,500 + 3,000 − 1,400 = $8,100.","In that example the $1,500 appears twice as a contra, once as a cash payment and once as a bank receipt; it is not a sale or expense. Discount columns total $100 on each side but are posted separately to discount allowed and discount received. To finish the cash column, put balance c/d $1,100 on the payment side and total both sides $3,000. Bring down $1,100 on the receipt side next period. The bank column is balanced independently.","For an analytical petty cash book, every payment appears in the total-payment column and exactly one appropriate analysis column unless a split is justified. Post the analysis totals to the respective expenses. A $200 postage payment is still only $200 of expenditure, even though it appears in the total and postage columns. Check that the analysis-column totals add to the total payments before calculating reimbursement."]},{"title":"Worked example","paragraphs":["A $5,000 petty cash float pays postage $800 and travel $1,250. Total spent $2,050; cash remaining $2,950; reimbursement $2,050 restores $5,000. If the float rises to $6,000, reimbursement becomes $3,050."]},{"title":"Common mistake","paragraphs":["A debit bank balance in the business cash book normally means money available; a bank statement describes the bank''s opposite perspective."]}],"keyPoints":["Deposit cash: debit bank and credit cash.","Petty cash spent + cash remaining should equal the float.","Reimbursement equals spending, adjusted for any agreed change in the float."],"summary":"The cash book records money received and paid. A contra transfers money within the business; an imprest replenishment restores petty cash to its agreed amount.","check":{"question":"Cash of $3,000 is deposited into the business bank. Is it income?","answer":"No. Debit bank $3,000 and credit cash $3,000: total business money is unchanged."},"flashcards":[{"front":"Cash of $3,000 is deposited into the business bank. Is it income?","back":"No. Debit bank $3,000 and credit cash $3,000: total business money is unchanged."},{"front":"What mistake should you avoid when studying cash books, contra entries and petty cash?","back":"A debit bank balance in the business cash book normally means money available; a bank statement describes the bank''s opposite perspective."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s4-lesson-10','poa-section-4','Double entry without guessing','Debit means left and credit means right. Neither word automatically means good, bad, increase or decrease. Asset and expense increases are debits. Liability, capital and income increases are credits. Decreases use the opposite side. Drawings reduce the owner''s interest and are normally debit entries. For every transaction, total debits must equal total credits.',9,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":15,"section":4,"objectiveCodes":["S4.1","S4.2","S4.3","S4.4"]},"lesson":{"introduction":"Debit means left and credit means right. Neither word automatically means good, bad, increase or decrease. Asset and expense increases are debits. Liability, capital and income increases are credits. Decreases use the opposite side. Drawings reduce the owner''s interest and are normally debit entries. For every transaction, total debits must equal total credits.","objectives":["describe the different classes of accounts","identify the different types of ledgers","explain the significance of debit and credit in each class of account","draw up simple account formats, neatly and accurately"],"sections":[{"title":"Understand the idea","paragraphs":["Nominal accounts contain income and expenses; real accounts contain assets; personal accounts record persons or organisations, including customer receivables and supplier payables. The sales ledger holds individual customer accounts, the purchases ledger individual suppliers, and the general ledger the remaining accounts. An account has its name, date, details, reference and amount on debit and credit sides, or a clearly labelled running-balance equivalent.","Use a three-step method: identify the accounts, decide how each changes, then apply the rule for its category. For cash sales, bank or cash increases and sales income increases: debit cash, credit sales. For paying rent, expense increases and bank decreases: debit rent, credit bank. A credit purchase increases purchases and the supplier liability: debit purchases, credit supplier. Explain the economic event before choosing sides.","Draw a T account with the account name above it, debit on the left and credit on the right. Both sides need date, details, folio or reference and amount. In the bank account a rent payment uses ''Rent'' as the details; in the rent account the matching debit uses ''Bank''. The details point to the other account. They help you trace the pair and do not change whether the entry belongs on the left or right.","For a mixed transaction, divide the effects before posting. Buy equipment for $12,000, pay $5,000 immediately and owe $7,000. Debit equipment $12,000; credit bank $5,000; credit supplier $7,000. There are three lines but total debits and credits still agree. A transaction does not have to contain exactly one debit and one credit; it must have equal total amounts on the two sides."]},{"title":"Worked example","paragraphs":["A customer pays $2,400 owed from last month. Bank is an asset increasing, so debit bank $2,400. The customer''s debt is an asset decreasing, so credit receivables $2,400. Sales is untouched because it was recorded when earned."]},{"title":"Common mistake","paragraphs":["The bank statement''s debit and credit labels cannot be copied mechanically into the business''s cash book."]}],"keyPoints":["Debit increases assets and expenses.","Credit increases liabilities, capital and income.","A later receipt from a customer clears the debt; it does not create another sale."],"summary":"For every transaction, identify the accounts, classify them and decide which increased or decreased. Equal debits and credits follow from that reasoning.","check":{"question":"Equipment costing $9,000 is bought on credit. Name the debit and credit.","answer":"Debit equipment $9,000 and credit the equipment supplier/payable $9,000."},"flashcards":[{"front":"Equipment costing $9,000 is bought on credit. Name the debit and credit.","back":"Debit equipment $9,000 and credit the equipment supplier/payable $9,000."},{"front":"What mistake should you avoid when studying double entry without guessing?","back":"The bank statement''s debit and credit labels cannot be copied mechanically into the business''s cash book."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s4-lesson-11','poa-section-4','Posting, balancing and trial balance','Post from original-entry books with a reference and the other account''s name. For a customer, debit credit sales and credit receipts, returns and discounts allowed. For a supplier, credit purchases and debit payments, returns and discounts received. Work chronologically and check each entry against the source. A customer credit balance can mean an overpayment; a supplier debit balance can mean money owed back to the business.',10,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":15,"section":4,"objectiveCodes":["S4.5","S4.6","S4.7","S4.8","S4.9"]},"lesson":{"introduction":"Post from original-entry books with a reference and the other account''s name. For a customer, debit credit sales and credit receipts, returns and discounts allowed. For a supplier, credit purchases and debit payments, returns and discounts received. Work chronologically and check each entry against the source. A customer credit balance can mean an overpayment; a supplier debit balance can mean money owed back to the business.","objectives":["post from books of original entry to the general ledger and the subsidiary ledgers","balance and close accounts","interpret entries and balances","use the balances brought down to construct the trial balance","outline the uses and limitations of the trial balance."],"sections":[{"title":"Understand the idea","paragraphs":["To balance an account, total each side, subtract the smaller total from the larger, enter balance c/d on the smaller side and total both equally. Bring that balance down on the other side in the new period. Income and expense accounts are closed to the income statement at period end; do not automatically carry them forward like assets and liabilities. Drawings close to capital.","A trial balance lists ledger balances at a date in debit and credit columns. Use balances, not the sums of all account entries. Cash, receivables, purchases, expenses and drawings are normally debit; capital, liabilities and income normally credit. Equal totals help detect one-sided postings and arithmetic mistakes. They do not detect complete omission, an entry in the wrong account of the same type, an error of principle, complete reversal, or equal errors on both sides.","Practise constructing a full small trial balance. An owner invests $20,000 in bank; the business buys equipment for $8,000 cash, buys resale goods for $6,000 on credit, makes cash sales $5,000, pays rent $1,000 and pays drawings $2,000. Bank closes at 20,000 − 8,000 + 5,000 − 1,000 − 2,000 = $14,000. Debit balances are bank $14,000, equipment $8,000, purchases $6,000, rent $1,000 and drawings $2,000: total $31,000.","The credit balances for that trial balance are capital $20,000, payables $6,000 and sales $5,000: total $31,000. This trial balance is prepared before year-end inventory and other adjustments. It does not itself calculate gross profit. When closing the year, transfer sales and returns inwards to the trading section; purchases and related costs also go there; other income and expenses go to profit and loss; the net result and drawings eventually change capital."]},{"title":"Worked example","paragraphs":["Customer account: opening debt $6,000 + sales $4,000 = debit $10,000. Receipts $7,000 and returns $500 total credit $7,500. Put balance c/d $2,500 on credit; next period bring down $2,500 debit. This is the amount still owed."]},{"title":"Common mistake","paragraphs":["Forcing an unexplained difference into an expense account hides the problem. Investigate it or use an explicitly temporary suspense account."]}],"keyPoints":["Balance c/d makes both sides total equally.","Balance b/d appears on the opposite side in the next period.","Investigate differences rather than forcing an unexplained expense."],"summary":"Post each side of the double entry, balance the account and bring the remaining balance into the next period. The trial balance then compares ledger debit and credit balances.","check":{"question":"Rent $700 was debited to repairs and bank correctly credited. Will the trial balance agree?","answer":"Yes. Both are expense accounts, so debit and credit totals agree despite the incorrect classification."},"flashcards":[{"front":"Rent $700 was debited to repairs and bank correctly credited. Will the trial balance agree?","back":"Yes. Both are expense accounts, so debit and credit totals agree despite the incorrect classification."},{"front":"What mistake should you avoid when studying posting, balancing and trial balance?","back":"Forcing an unexplained difference into an expense account hides the problem. Investigate it or use an explicitly temporary suspense account."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-12','poa-section-5','Build a sole trader''s income statement','An income statement explains profit for a period. Start with net sales: sales less returns inwards. Calculate cost of goods sold: opening inventory + net purchases + carriage inwards − closing inventory. Net purchases are purchases less returns outwards. Carriage inwards brings inventory to the business and is included in its cost; carriage outwards delivers sales to customers and is a selling expense.',11,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.1","S5.2","S5.3"]},"lesson":{"introduction":"An income statement explains profit for a period. Start with net sales: sales less returns inwards. Calculate cost of goods sold: opening inventory + net purchases + carriage inwards − closing inventory. Net purchases are purchases less returns outwards. Carriage inwards brings inventory to the business and is included in its cost; carriage outwards delivers sales to customers and is a selling expense.","objectives":["explain the purpose of preparing financial statements","identify the components of the Financial Statements","draw up the income statement for sole traders to determine gross profit or loss and net profit or loss"],"sections":[{"title":"Understand the idea","paragraphs":["Gross profit = net sales − cost of goods sold. Add other income and deduct operating expenses to find net profit. Expenses can include rent, wages, advertising, carriage outwards, depreciation and bad debts. Apply period-end adjustments before finishing. Give the business name and ''for the year ended'' date. The trading section explains buying and selling goods; the profit and loss section accounts for other income and running costs.","Closing inventory is unsold goods, so its cost is removed from this period''s cost of sales and also shown as a current asset. If closing inventory is overstated, cost of sales is understated and profit overstated. Drawings of goods reduce purchases or the relevant inventory cost account and increase drawings; they are not sales at a profit unless the facts describe an actual sale.","Use a repeated layout when information is mixed: net sales, cost of sales, gross profit, other income, then operating expenses. Cross out each trial-balance item only after giving it its correct destination. Assets, liabilities, capital and drawings do not become expenses merely because they appear in the trial balance. The closing inventory supplied as an adjustment normally affects both cost of sales and the balance sheet.","A second example includes goods withdrawn by the owner. Purchases are $50,000 before recording goods costing $2,000 taken privately. Debit drawings $2,000 and credit purchases $2,000, making adjusted purchases $48,000. Opening inventory $10,000, carriage inwards $1,000 and closing inventory $12,000 then give cost of sales 10,000 + 48,000 + 1,000 − 12,000 = $47,000. With net sales $80,000, gross profit is $33,000. The $2,000 drawings also reduces closing capital.","When costs exceed net sales, show a gross loss rather than changing signs to manufacture profit. Net sales $40,000 and cost of sales $45,000 give gross loss $5,000. Other income $1,000 and operating expenses $8,000 give net loss $12,000: −5,000 + 1,000 − 8,000. That loss reduces capital. State the label clearly so a reader can tell whether the amount is favourable or unfavourable."]},{"title":"Worked example","paragraphs":["Sales $120,000, returns inwards $4,000, opening inventory $15,000, purchases $70,000, returns outwards $2,000, carriage inwards $3,000 and closing inventory $18,000. Net sales = $116,000; cost of sales = 15,000 + 70,000 − 2,000 + 3,000 − 18,000 = $68,000; gross profit = $48,000. Other income $1,000 less expenses $31,000 gives net profit $18,000."]},{"title":"Common mistake","paragraphs":["Returns inwards reduce sales; returns outwards reduce purchases. Do not swap them."]}],"keyPoints":["Net sales = sales − returns inwards.","Cost of sales = opening inventory + net purchases + carriage inwards − closing inventory.","Net profit = gross profit + other income − expenses."],"summary":"Build profit in stages: net sales, cost of sales, gross profit and then net profit. Keep inventory adjustments and operating expenses in their proper places.","check":{"question":"Closing inventory rises by $2,000 with everything else unchanged. What happens to profit?","answer":"Cost of sales falls by $2,000, so profit rises by $2,000."},"flashcards":[{"front":"Closing inventory rises by $2,000 with everything else unchanged. What happens to profit?","back":"Cost of sales falls by $2,000, so profit rises by $2,000."},{"front":"What mistake should you avoid when studying build a sole trader''s income statement?","back":"Returns inwards reduce sales; returns outwards reduce purchases. Do not swap them."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-13','poa-section-5','Working capital and closing capital','Working capital = current assets − current liabilities. It measures the net short-term resources available to support operations. Inventory must be bought, customers may take time to pay and wages fall due even before sales are collected. Positive working capital helps, but slow-moving stock or doubtful receivables may still create cash problems. Negative working capital is a warning to investigate rather than a complete diagnosis by itself.',12,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.4","S5.5","S5.8"]},"lesson":{"introduction":"Working capital = current assets − current liabilities. It measures the net short-term resources available to support operations. Inventory must be bought, customers may take time to pay and wages fall due even before sales are collected. Positive working capital helps, but slow-moving stock or doubtful receivables may still create cash problems. Negative working capital is a warning to investigate rather than a complete diagnosis by itself.","objectives":["prepare classified balance sheet in vertical style","explain the significance of the working capital for the operation of a business","show the effect of net profit or loss on capital"],"sections":[{"title":"Understand the idea","paragraphs":["In a classified vertical balance sheet, show non-current assets at cost less accumulated depreciation; list current assets; deduct current liabilities for working capital; combine with net non-current assets and deduct non-current liabilities. The result is net assets financed by the owner. Closing capital = opening capital + additional capital + net profit − drawings. Replace net profit with a deduction for a net loss.","A loan repayment can include principal and interest. Principal reduces the liability and bank; interest is an expense. Drawings reduce capital but do not reduce the profit earned by the business. A balance sheet is ''as at'' one date, while the income statement covers a period. Check that net assets equal closing capital; if they do not, trace the underlying balances rather than editing capital to make it fit.","Connect profit and position with a complete equity check. Opening capital $40,000, additional investment $5,000, profit $15,000 and drawings $10,000 give closing capital $50,000. Suppose net equipment is $48,000, current assets $24,000, current liabilities $10,000 and a long-term loan $12,000. Net assets are 48,000 + 24,000 − 10,000 − 12,000 = $50,000. The agreement checks the route from profit to the owner''s closing interest.","Cash management can improve without changing profit immediately. Collecting $3,000 from customers increases bank and reduces receivables by the same amount; total current assets and working capital are unchanged. Buying inventory for cash changes the composition of current assets, not their total. Paying a current payable reduces current assets and current liabilities equally, so working capital stays unchanged. These changes can still affect immediate cash availability and particular liquidity ratios.","Extension — using capital when records are incomplete: first calculate capital as assets less liabilities at the opening and closing dates. Then rearrange the capital equation: profit = closing capital + drawings − additional capital − opening capital. For opening capital $45,000, closing assets $80,000, closing liabilities $20,000, drawings $8,000 and additional investment $5,000, closing capital is $60,000 and profit is 60,000 + 8,000 − 5,000 − 45,000 = $18,000. This assumes the capital changes are fully identified; it does not rebuild missing sales, expenses or cash records by itself."]},{"title":"Worked example","paragraphs":["Current assets $38,000 less current liabilities $16,000 give working capital $22,000. Non-current assets $60,000 plus working capital $22,000 less long-term loan $20,000 give net assets $62,000. Opening capital $50,000 + profit $18,000 − drawings $6,000 also equals $62,000."]},{"title":"Common mistake","paragraphs":["Net profit is not the same as the closing capital balance, and drawings are not wages paid to the owner."]}],"keyPoints":["Working capital = current assets − current liabilities.","Closing capital = opening capital + additional capital + profit − drawings.","Closing capital should agree with net assets."],"summary":"Working capital measures the short-term asset cushion. Closing capital explains how the owner''s interest changed through investment, profit and drawings.","check":{"question":"Opening capital $30,000, new investment $4,000, loss $2,000 and drawings $5,000: closing capital?","answer":"$30,000 + $4,000 − $2,000 − $5,000 = $27,000."},"flashcards":[{"front":"Opening capital $30,000, new investment $4,000, loss $2,000 and drawings $5,000: closing capital?","back":"$30,000 + $4,000 − $2,000 − $5,000 = $27,000."},{"front":"What mistake should you avoid when studying working capital and closing capital?","back":"Net profit is not the same as the closing capital balance, and drawings are not wages paid to the owner."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-14','poa-section-5','Ratios that lead to useful recommendations','Gross profit margin = gross profit ÷ net sales × 100. Net profit margin = net profit ÷ net sales × 100. Mark-up = gross profit ÷ cost of sales × 100; it uses a different denominator. Average inventory = (opening + closing inventory) ÷ 2. Inventory turnover = cost of sales ÷ average inventory, expressed in times per period. A low turnover can suggest slow stock but depends on the type of business.',13,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.6","S5.7","S5.9"]},"lesson":{"introduction":"Gross profit margin = gross profit ÷ net sales × 100. Net profit margin = net profit ÷ net sales × 100. Mark-up = gross profit ÷ cost of sales × 100; it uses a different denominator. Average inventory = (opening + closing inventory) ÷ 2. Inventory turnover = cost of sales ÷ average inventory, expressed in times per period. A low turnover can suggest slow stock but depends on the type of business.","objectives":["use ratios to determine the performance (profitability) of the business","calculate ratios to demonstrate the financial position of a business","make recommendations about a business based on ratio analysis."],"sections":[{"title":"Understand the idea","paragraphs":["Current ratio = current assets ÷ current liabilities. Acid test = (current assets − inventory) ÷ current liabilities. Express these as x:1. Return on capital employed/investment = the relevant profit ÷ capital employed × 100; use the definition, opening/average basis and profit measure requested. Do not silently use sales as the denominator. A ratio with a zero denominator is undefined, not zero.","Compare periods, similar businesses and the information behind the figures. A rising gross margin may reflect higher prices or lower buying costs. A falling net margin despite a steady gross margin points towards operating expenses. Explain the cause as a possibility, then recommend a specific action and acknowledge limitations. Ratios alone do not prove mismanagement or predict survival.","Show the substituted figures and the unit in every ratio answer. If annual cost of sales is $90,000, opening inventory $12,000 and closing inventory $18,000, average inventory is $15,000 and turnover is 90,000/15,000 = 6 times. If asked for an inventory holding period, use the question''s day basis: 365/6 is approximately 61 days. A turnover of 6 is not 6%, and the current ratio 2:1 is not automatically evidence that every bill can be paid today.","Interpret a paired comparison. Business A has current assets $60,000, including inventory $45,000, and current liabilities $30,000: current ratio 2:1 but acid test 0.5:1. Business B has the same current assets and liabilities but inventory $15,000: acid test 1.5:1. Their current ratios match, yet A depends more heavily on selling inventory. Investigate slow or damaged stock and customer collections before recommending action; neither ratio alone proves the inventory will sell.","For return on capital employed, match numerator to denominator as instructed. If the exercise defines it as net profit divided by opening capital, $12,000/$60,000 × 100 = 20%. If it asks for average capital and capital rises from $60,000 to $80,000, average capital is $70,000 and the result is 17.14%. State the basis. Do not compare differently defined returns as though they were directly equivalent."]},{"title":"Worked example","paragraphs":["Net sales $100,000, cost of sales $60,000, net profit $10,000 and average inventory $15,000 give gross margin 40%, net margin 10%, mark-up 66.67% and turnover 4 times. Current assets $30,000 including stock $12,000, current liabilities $15,000: current ratio 2:1; acid test 1.2:1. Recommend collecting overdue debts if receivables are tying up cash."]},{"title":"Common mistake","paragraphs":["A 25% mark-up is a 20% margin: cost $100, profit $25, selling price $125."]}],"keyPoints":["Distinguish mark-up on cost from margin on sales.","Current and acid-test ratios assess different degrees of liquidity.","State the capital base used for return on capital employed."],"summary":"A useful ratio answer gives the formula, substitutes the correct figures and explains what the result means. Base any recommendation on the business''s circumstances.","check":{"question":"Gross margin stays at 30% while net margin falls from 12% to 7%. What should be investigated?","answer":"Operating expenses relative to sales, along with changes in other income, rather than assuming buying costs caused the whole decline."},"flashcards":[{"front":"Gross margin stays at 30% while net margin falls from 12% to 7%. What should be investigated?","back":"Operating expenses relative to sales, along with changes in other income, rather than assuming buying costs caused the whole decline."},{"front":"What mistake should you avoid when studying ratios that lead to useful recommendations?","back":"A 25% mark-up is a 20% margin: cost $100, profit $25, selling price $125."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-15','poa-section-6','Accruals and prepayments, step by step','Adjustments put income and expenses in the period to which they belong. An accrued expense has been incurred but not paid: add it to the expense and show a current liability. A prepaid expense has been paid for a future period: deduct it from the expense and show a current asset. The money paid and the period''s cost therefore need not match.',14,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.1","S6.2","S6.3","S6.11","S6.12","S6.13"]},"lesson":{"introduction":"Adjustments put income and expenses in the period to which they belong. An accrued expense has been incurred but not paid: add it to the expense and show a current liability. A prepaid expense has been paid for a future period: deduct it from the expense and show a current asset. The money paid and the period''s cost therefore need not match.","objectives":["explain accounting concepts that underpin the need for adjustments","explain why adjustments are made to financial statements","prepare journal entries and ledger accounts to reflect adjustments and the treatment in the balance sheet","determine the amount of expenses or revenues to be transferred to the Income Statement","prepare income statements to reflect adjusting entries","prepare Financial Statements after adjustments"],"sections":[{"title":"Understand the idea","paragraphs":["For an expense, start with cash paid, add closing accrual, subtract opening accrual, add opening prepayment and subtract closing prepayment. For income, start with cash received, add closing accrued income, subtract opening accrued income, add opening income received in advance and subtract closing income received in advance. Write a timeline when dates span years. Apportion evenly only when the question supports that assumption.","Closing expense accrual: debit expense, credit accrued expense. Closing prepayment: debit prepaid expense, credit expense. Accrued income: debit income receivable, credit income. Income received in advance: debit income, credit deferred income. Transfer the adjusted income and expense balances to the income statement, and put the remaining assets and liabilities on the balance sheet. An adjusted trial balance helps you check both sides of each adjustment.","An expense ledger explains the adjustment formula. Wages owing at the start were $1,000; during the year bank pays $21,000; wages owing at the end are $2,500. The $21,000 payment includes clearing last year''s $1,000, leaving $20,000 paid for this year. Add $2,500 still owing: expense $22,500. Close that expense to profit and loss and bring forward the $2,500 liability. A ledger balance and the expense transferred are different amounts.","For an income example, commission cash received is $9,000, opening commission receivable $800 and closing commission receivable $1,200. This year''s income is 9,000 − 800 + 1,200 = $9,400. If $600 of the receipts instead relates to next year and there was no opening advance, income becomes $8,800. Show closing receivable $1,200 as a current asset and income in advance $600 as a current liability. Do not offset them invisibly.","Complete an adjusted income statement in one sequence. Net sales $100,000 less cost of sales $60,000 gives gross profit $40,000. Rent paid $12,000 includes closing prepayment $2,000, so rent expense is $10,000. Wages paid $8,000 plus closing accrual $1,000 gives expense $9,000. Add depreciation $3,000, bad debts $500 and allowance increase $200: total expenses $22,700. Net profit is $17,300. Each adjustment has a balance-sheet destination as well as its profit effect.","Finish the related position example to check both statements. Equipment cost $40,000 less accumulated depreciation $10,000 gives $30,000. Inventory $15,000, receivables after write-off $10,000 less closing allowance $500, bank $5,000 and rent prepayment $2,000 give current assets $31,500. Payables $8,000 plus wages accrual $1,000 give current liabilities $9,000. With long-term loan $10,000, net assets are 30,000 + 31,500 − 9,000 − 10,000 = $42,500. Opening capital $30,000 + profit $17,300 − drawings $4,800 also gives $42,500."]},{"title":"Worked example","paragraphs":["Rent paid $36,000 covers 1 April to 31 March; the business year ends 31 December. Three months belong to next year: prepaid rent = 36,000 × 3/12 = $9,000. This year''s rent from that payment is $27,000. Debit prepaid rent $9,000 and credit rent expense $9,000. Show the $9,000 as a current asset."]},{"title":"Common mistake","paragraphs":["Adding a prepayment to expense charges next year''s cost to this year. Check the period, not just the payment date."]}],"keyPoints":["Add closing expense accruals and remove closing prepayments from cash-based expense calculations.","Accrued expenses are liabilities; prepaid expenses are assets.","Reverse the opening timing adjustments when calculating the current period''s expense."],"summary":"Adjust expenses and income to the period they belong to, then carry the remaining asset or liability into the balance sheet. Cash paid is only the starting point.","check":{"question":"Wages paid $21,000; opening wages owing $1,000; closing wages owing $2,500. Find wages expense.","answer":"$21,000 − $1,000 + $2,500 = $22,500. The opening liability belonged to last period."},"flashcards":[{"front":"Wages paid $21,000; opening wages owing $1,000; closing wages owing $2,500. Find wages expense.","back":"$21,000 − $1,000 + $2,500 = $22,500. The opening liability belonged to last period."},{"front":"What mistake should you avoid when studying accruals and prepayments, step by step?","back":"Adding a prepayment to expense charges next year''s cost to this year. Check the period, not just the payment date."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-16','poa-section-6','Bad debts and doubtful debt allowances','A bad debt is a specific amount judged irrecoverable. A doubtful debt allowance estimates how much of the remaining receivables may not be collected. Customers may become insolvent, dispute balances or repeatedly fail to pay. An aged receivables list groups debts by how long they have been outstanding and supports a reasoned estimate.',15,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.4","S6.5","S6.6"]},"lesson":{"introduction":"A bad debt is a specific amount judged irrecoverable. A doubtful debt allowance estimates how much of the remaining receivables may not be collected. Customers may become insolvent, dispute balances or repeatedly fail to pay. An aged receivables list groups debts by how long they have been outstanding and supports a reasoned estimate.","objectives":["explain the reasons for bad debts","prepare journal entries and ledger accounts to write off bad debts and create provision for doubtful debts","indicate the treatment of bad and doubtful debts in the Income Statement and Balance Sheet"],"sections":[{"title":"Understand the idea","paragraphs":["Write off an irrecoverable debt by debiting bad debts expense and crediting the customer''s account or receivables control. Then calculate the required closing allowance on the remaining eligible receivables, using the question''s percentage or specific estimates. To create or increase an allowance, debit doubtful debts expense and credit allowance for doubtful debts. A decrease reverses that movement.","The income statement includes the specific bad debts plus the increase in allowance, or subtracts the decrease. The balance sheet shows trade receivables after write-offs, less the closing allowance. The allowance is a deduction from the asset, not a cash fund or a separate liability owed to someone. Do not charge the full closing allowance as an expense if an opening allowance already exists.","Use the allowance account to separate stock and movement. With opening allowance credit $1,500 and closing requirement credit $1,900, only $400 more is needed: debit allowance expense $400 and credit allowance $400. The final credit balance $1,900 is deducted from receivables. If the next closing requirement falls to $1,200, debit allowance $700 and credit the allowance expense adjustment $700. This releases part of the earlier estimate; it is not a customer cash receipt.","An aged-debt exercise may apply different risks to different groups. After writing off named irrecoverable debts, suppose $20,000 is assessed at 2% and $5,000 at 10%. Required allowance is $400 + $500 = $900, rather than 12% of $25,000. The percentages apply to their own groups. A later recovery of a debt already written off is a separate event; follow the stated recovery method and do not reinstate both a debt and a receipt without clearing the account."]},{"title":"Worked example","paragraphs":["Receivables $40,000 include a $2,000 irrecoverable debt. Write it off, leaving $38,000. Required allowance at 5% = $1,900. If opening allowance was $1,500, the increase is $400. Income statement charge = bad debt $2,000 + increase $400 = $2,400. Balance sheet receivables = $38,000 − $1,900 = $36,100."]},{"title":"Common mistake","paragraphs":["Calculate the percentage after writing off the named bad debt unless the question explicitly says otherwise."]}],"keyPoints":["Bad debt: debit expense and credit the customer''s account.","The income statement records an allowance increase or decrease.","The balance sheet shows receivables less the closing allowance."],"summary":"Write off debts known to be irrecoverable before calculating an allowance on the remaining receivables. Distinguish the closing allowance from the year''s change in allowance.","check":{"question":"Required allowance is $900 and existing allowance is $1,200. What is the period''s movement?","answer":"A $300 decrease: debit allowance and credit the doubtful debts expense/income statement adjustment $300."},"flashcards":[{"front":"Required allowance is $900 and existing allowance is $1,200. What is the period''s movement?","back":"A $300 decrease: debit allowance and credit the doubtful debts expense/income statement adjustment $300."},{"front":"What mistake should you avoid when studying bad debts and doubtful debt allowances?","back":"Calculate the percentage after writing off the named bad debt unless the question explicitly says otherwise."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-17','poa-section-6','Depreciation and expenditure','Depreciation allocates a depreciable asset''s cost over its useful life. Wear, use, passage of time and obsolescence can reduce usefulness. It is not a savings fund and does not try to measure an asset''s exact resale value each year. Consider cost, expected residual value and useful life, and follow the stated policy for assets bought during the year.',16,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.7","S6.8","S6.9","S6.10"]},"lesson":{"introduction":"Depreciation allocates a depreciable asset''s cost over its useful life. Wear, use, passage of time and obsolescence can reduce usefulness. It is not a savings fund and does not try to measure an asset''s exact resale value each year. Consider cost, expected residual value and useful life, and follow the stated policy for assets bought during the year.","objectives":["discuss the nature of depreciation","calculate annual depreciation expenses using straight line method and reducing balance method;","prepare journal entries and ledger accounts for provision for depreciation","distinguish between capital expenditure and revenue expenditures"],"sections":[{"title":"Understand the idea","paragraphs":["Straight-line annual depreciation = (cost − residual value) ÷ useful life. When the question specifies a percentage of cost, apply that stated rate consistently. Reducing balance depreciation = opening carrying amount × rate. Carrying amount, also called net book value, equals cost less accumulated depreciation. Under reducing balance the charge normally falls each year; straight-line normally gives a constant full-year charge.","Debit depreciation expense and credit accumulated depreciation. Show cost less accumulated depreciation on the balance sheet. Capital expenditure acquires or improves a non-current asset and is initially recorded as an asset; revenue expenditure maintains operations and is charged as an expense. Installation needed to bring new equipment into use can form part of cost; routine repairs normally do not. Misclassifying a repair as an asset overstates profit and assets.","Keep the asset-at-cost and accumulated-depreciation accounts separate. Equipment cost is $24,000 and straight-line annual depreciation $5,000. After year one the asset account still shows $24,000, the accumulated depreciation account has a $5,000 credit, and carrying amount is $19,000. After year two accumulated depreciation is $10,000 and carrying amount $14,000. The year''s expense is $5,000, not the whole accumulated $10,000.","Apportion only according to the policy supplied. If a $30,000 machine is depreciated at 10% of cost per year from its purchase date, and is bought on 1 July in a year ending 31 December, the six-month charge is 30,000 × 10% × 6/12 = $1,500. If the question instead says a full year''s charge in the year of purchase, use $3,000. Make the policy visible in the working rather than assuming one convention applies to every exercise.","Classify each part of an expenditure invoice. A machine costs $20,000, delivery $1,000 and installation $2,000 to bring it into use: initial asset cost is $23,000 under those facts. A later routine service costing $600 is an expense. If that service is incorrectly added to the asset, current profit and the asset are initially overstated by $600 before considering any consequential depreciation. A genuine improvement requires different treatment from routine maintenance."]},{"title":"Worked example","paragraphs":["Equipment costs $50,000 with residual value $5,000 and five-year life. Straight-line charge = (50,000 − 5,000)/5 = $9,000 each full year; after two years carrying amount = $32,000. At 20% reducing balance with no separate residual adjustment, year 1 charge $10,000, carrying amount $40,000; year 2 charge $8,000, carrying amount $32,000."]},{"title":"Common mistake","paragraphs":["Use opening carrying amount for reducing balance, not the original cost every year. Do not depreciate below the specified residual value."]}],"keyPoints":["Straight-line depreciation uses a consistent depreciable base.","Reducing-balance depreciation uses the remaining carrying amount.","Ordinary repairs are revenue expenditure; improvements that add lasting benefits may be capital expenditure."],"summary":"Depreciation spreads an asset''s depreciable amount across its useful life. Classify spending by its purpose before deciding whether it belongs in an asset or expense account.","check":{"question":"A machine costs $24,000, residual $4,000, useful life four years. Annual straight-line depreciation?","answer":"($24,000 − $4,000)/4 = $5,000."},"flashcards":[{"front":"A machine costs $24,000, residual $4,000, useful life four years. Annual straight-line depreciation?","back":"($24,000 − $4,000)/4 = $5,000."},{"front":"What mistake should you avoid when studying depreciation and expenditure?","back":"Use opening carrying amount for reducing balance, not the original cost every year. Do not depreciate below the specified residual value."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-18','poa-section-7','Correcting errors and using suspense','Controls help detect mistakes, protect assets and support reliable reports. The three record-checking systems studied here are suspense accounts, receivables/payables control accounts and bank reconciliation statements. Reconciliations compare independent records; authorisation and separation of duties also reduce opportunities for error or misuse. A suspense account temporarily holds a trial balance difference while its causes are investigated. It is not income, an expense or a permanent solution.',17,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":21,"section":7,"objectiveCodes":["S7.1","S7.2","S7.3","S7.4","S7.5","S7.6","S7.7"]},"lesson":{"introduction":"Controls help detect mistakes, protect assets and support reliable reports. The three record-checking systems studied here are suspense accounts, receivables/payables control accounts and bank reconciliation statements. Reconciliations compare independent records; authorisation and separation of duties also reduce opportunities for error or misuse. A suspense account temporarily holds a trial balance difference while its causes are investigated. It is not income, an expense or a permanent solution.","objectives":["explain the uses of control systems in the accounting process","outline the THREE most commonly used control systems in the accounting process","distinguish between those errors which affect and those which do not affect the trial balance","prepare journal entries for the correction of errors","explain the need for suspense account","construct a suspense account","construct a statement of revised profit after the correction of errors"],"sections":[{"title":"Understand the idea","paragraphs":["Errors that disturb debit-credit agreement include a one-sided omission, unequal amounts and putting an amount on the wrong side. Complete omission, wrong-account errors, errors of principle, complete reversal and equal wrong amounts on both sides can leave the trial balance balanced. For each correction, first write the entry that should have been made, compare it with the entry actually made, then record only the difference.","If debit balances exceed credits, a temporary credit suspense balance restores agreement; if credits exceed debits, suspense begins as a debit. Correct known errors with journal entries and post any required suspense entries until its balance is zero. Revise profit only for errors affecting income or expenses. Correcting an asset-to-asset classification changes the balance sheet but not profit. Drawings wrongly treated as an expense understated profit.","A wrong-side posting usually needs twice the amount to correct it. Bank was correctly credited $400 for rent, but rent was also credited $400 instead of debited. Remove the incorrect credit with a $400 debit and enter the correct $400 debit: debit rent $800 and credit suspense $800. The net trial-balance difference from this error is $800, although the actual rent expense is $400. Write the actual and correct entries side by side to see why.","Construct a suspense account with several errors. Before correction credits exceed debits by $1,400, so suspense opens with a $1,400 debit. Rent $600 was omitted from its debit account: debit rent and credit suspense $600. Separately rent $400 was posted on the wrong side as above: debit rent and credit suspense $800. Suspense now has debit $1,400 and credits $1,400, so it closes. If it does not reach zero, investigate the remaining difference instead of transferring it to profit.","Prepare a revised-profit statement separately. Start with draft net profit $20,000. Deduct omitted rent $600 and the $800 effect of correcting the wrong-side rent: the original credit had wrongly increased profit by $400 and the correct debit must reduce it by $400. Add $2,000 for equipment wrongly charged to purchases and add $500 for the owner''s drawings wrongly included in wages. Revised profit is 20,000 − 600 − 800 + 2,000 + 500 = $21,100. Corrections between two asset accounts have no profit adjustment.","Name balanced errors accurately. A purchase completely left out is an omission; entering it in the wrong supplier''s account is an error of commission; charging equipment to purchases is an error of principle; swapping the debit and credit is complete reversal; using $450 instead of $540 on both sides is an error of original entry. Compensating errors happen when separate mistakes cancel in total. A balanced trial balance can contain any of these."]},{"title":"Worked example","paragraphs":["Rent $600 was correctly credited to bank but omitted from rent. Credits exceed debits by $600, so suspense initially has a $600 debit. Correct by debit rent $600 and credit suspense $600; profit falls $600. Separately, equipment $2,000 wrongly debited to purchases: debit equipment $2,000, credit purchases $2,000. Profit rises $2,000; no suspense entry is needed."]},{"title":"Common mistake","paragraphs":["Do not use suspense for an error that already has equal debit and credit effects."]}],"keyPoints":["Some omissions, classification errors and reversals leave the trial balance equal.","A wrong-side posting may need twice the original amount to correct it.","Only corrections affecting income or expenses change the reported profit."],"summary":"Correct the entry that should have been made, taking account of what is already in the ledger. Use suspense only for differences that affect trial-balance agreement.","check":{"question":"Sales of $750 were recorded on both sides as $570. What correction is required?","answer":"Increase receivables by a $180 debit and sales by a $180 credit. The trial balance had agreed; profit rises $180."},"flashcards":[{"front":"Sales of $750 were recorded on both sides as $570. What correction is required?","back":"Increase receivables by a $180 debit and sales by a $180 credit. The trial balance had agreed; profit rises $180."},{"front":"What mistake should you avoid when studying correcting errors and using suspense?","back":"Do not use suspense for an error that already has equal debit and credit effects."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-19','poa-section-7','Receivables and payables control accounts','A control account summarises a subsidiary ledger so its total can be checked against the list of individual balances. Use independently totalled day books, cash books and journals. If the same inaccurate total is copied into both records, agreement is weaker evidence. Controls help locate errors but do not prove every personal account is correct.',18,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":21,"section":7,"objectiveCodes":["S7.8","S7.9","S7.10","S7.11"]},"lesson":{"introduction":"A control account summarises a subsidiary ledger so its total can be checked against the list of individual balances. Use independently totalled day books, cash books and journals. If the same inaccurate total is copied into both records, agreement is weaker evidence. Controls help locate errors but do not prove every personal account is correct.","objectives":["explain the purposes of control accounts and how they are prepared","identify the sources of information for entries made in control accounts","construct sales and purchases ledger control accounts","explain the significance of the balances on control accounts;"],"sections":[{"title":"Understand the idea","paragraphs":["Receivables control normally begins with a debit. Debit credit sales, dishonoured customer cheques and interest charged where specified. Credit receipts, sales returns, discounts allowed and bad debts. A contra set-off against a supplier account credits receivables control and debits payables control. Do not include cash sales because no customer debt is created.","Payables control normally begins with a credit. Credit credit purchases and any reinstated supplier debts. Debit payments, purchases returns, discounts received and contra set-offs. Calculate the closing balance and compare with the subsidiary ledger schedule. Abnormal opposite-side balances can arise from overpayments and should be shown separately where required rather than silently netted away. A receivables credit balance may mean the business owes a customer a refund.","Link each control entry to its evidence. Credit-sales totals come from the sales day book, returns inwards from the returns-inwards book, customer receipts and discounts from the cash book, and write-offs or contra transfers from authorised journals. Payables use the corresponding purchase, return and payment records. Cash sales and cash purchases do not create a personal balance and are excluded from these credit-ledger controls. General expenses owing do not automatically belong in trade-payables control.","Show abnormal balances without losing the normal ones. Receivables control opens with debit balances $20,000 and credit balances $600. During the period credit sales $50,000 and dishonoured cheques $1,000 are debits; receipts $45,000, returns $2,000, discounts $900, bad debts $500 and contra $300 are credits. If closing customer credit balances total $800, the debit balances due from other customers are $22,500. Check the equation: 20,000 + 50,000 + 1,000 + 800 = 600 + 45,000 + 2,000 + 900 + 500 + 300 + 22,500 = $71,800.","In that example place the closing debit balance $22,500 on the credit side as balance c/d and the closing credit balance $800 on the debit side as balance c/d. Bring them down on their normal opposite sides next period. Net receivables are $21,700, but the separate $800 indicates obligations to particular customers. For payables the usual closing balance is credit; a supplier debit balance is the opposite exception. Follow the requested presentation rather than silently merging different customers or suppliers.","To investigate disagreement, identify which record contains the error. Control shows $19,000 but the customers'' schedule totals $18,700. An invoice $300 omitted from one customer''s personal account increases the schedule to $19,000; control is already correct. A sales-day-book total understated by $300 would instead require a control correction if individual postings were correct. Do not adjust both records automatically: that can preserve the difference or create a new error."]},{"title":"Worked example","paragraphs":["Receivables: opening $12,000 + credit sales $40,000 − receipts $30,000 − returns $1,000 − discount $500 − bad debt $1,500 = closing debit $19,000. Payables: opening $9,000 + credit purchases $25,000 − payments $20,000 − returns $2,000 − discount received $500 = closing credit $11,500."]},{"title":"Common mistake","paragraphs":["Customer refunds and dishonoured cheques reverse earlier effects; identify what is being reversed before choosing a side."]}],"keyPoints":["Receivables normally have debit balances; payables normally have credit balances.","Receipts and returns reduce receivables; payments and returns reduce payables.","A correction may belong in the control account, the individual ledger or both."],"summary":"A control account summarises the individual customer or supplier accounts. Reconcile the control total with the schedule to locate errors and omissions.","check":{"question":"Why is a credit sale included in receivables control but a cash sale excluded?","answer":"A credit sale creates a customer debt. A cash sale is settled immediately and creates no receivable."},"flashcards":[{"front":"Why is a credit sale included in receivables control but a cash sale excluded?","back":"A credit sale creates a customer debt. A cash sale is settled immediately and creates no receivable."},{"front":"What mistake should you avoid when studying receivables and payables control accounts?","back":"Customer refunds and dishonoured cheques reverse earlier effects; identify what is being reversed before choosing a side."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-20','poa-section-7','Bank reconciliation that actually reconciles','The cash book is the business''s bank record; the bank statement is the bank''s record. They differ when one side knows about an event first, when clearing takes time, or when an error occurs. Bank charges, standing orders, direct debits, direct credits, interest and dishonoured cheques may appear on the statement before the business records them.',19,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":22,"section":7,"objectiveCodes":["S7.12","S7.13"]},"lesson":{"introduction":"The cash book is the business''s bank record; the bank statement is the bank''s record. They differ when one side knows about an event first, when clearing takes time, or when an error occurs. Bank charges, standing orders, direct debits, direct credits, interest and dishonoured cheques may appear on the statement before the business records them.","objectives":["identify items that will result in differences between cash book and bank statement balances","construct a bank reconciliation statement using the adjusted cash book balance"],"sections":[{"title":"Understand the idea","paragraphs":["First update the cash book for valid transactions missing from it and correct cash book errors. A bank charge reduces the business bank asset; a direct customer deposit increases it. A dishonoured customer cheque reverses the earlier receipt: debit customer and credit bank. Do not adjust the cash book again for a cheque already recorded but not yet presented or a lodgement awaiting bank processing.","Then prepare the reconciliation using only remaining timing differences and bank errors. With a positive adjusted cash book balance, add unpresented cheques and deduct outstanding lodgements to derive the positive bank statement balance. To move from statement to cash book, reverse those signs. Treat overdrafts as signed negative balances to keep the logic consistent. Explain each difference and confirm that the computed balance matches the actual statement.","Keep two named workings: adjusted cash book and bank reconciliation statement. Cash book starts with a debit $6,400. Deduct bank charges $100 and a dishonoured customer cheque $800, then add a direct credit $500: adjusted debit balance is $6,000. The journal for the dishonoured cheque debits the customer $800 and credits bank $800, restoring the customer''s debt. No fresh sale is recorded.","Suppose the statement in that example shows $5,500, cheques issued but not presented total $1,200, and lodgements not credited total $1,700. Starting at adjusted cash book, 6,000 + 1,200 − 1,700 = $5,500, matching the statement. Starting at the statement, 5,500 − 1,200 + 1,700 = $6,000. Use the second route as a check. A bank error stays in the reconciliation until the bank corrects it; a business-book error is corrected in the cash book."]},{"title":"Worked example","paragraphs":["Cash book $8,000; bank charge $200 not recorded; direct customer receipt $1,000 not recorded. Adjusted cash book = 8,000 − 200 + 1,000 = $8,800. Unpresented cheques $1,500 and outstanding lodgements $2,300 give statement balance 8,800 + 1,500 − 2,300 = $8,000. The equal starting figures had concealed real differences."]},{"title":"Common mistake","paragraphs":["Do not post unpresented cheques into the cash book a second time; they are already recorded there."]}],"keyPoints":["Bank charges, direct debits and dishonoured receipts may require cash-book entries.","Unpresented cheques and deposits not yet credited are timing differences.","Choose a starting balance and keep the reconciliation direction consistent."],"summary":"Update the business cash book for newly discovered transactions first. Then reconcile its adjusted balance with the bank statement using timing differences.","check":{"question":"Adjusted cash book is an overdraft $2,000, unpresented cheques $500, outstanding lodgements $300. Statement balance?","answer":"−2,000 + 500 − 300 = −$1,800, a statement overdraft of $1,800."},"flashcards":[{"front":"Adjusted cash book is an overdraft $2,000, unpresented cheques $500, outstanding lodgements $300. Statement balance?","back":"−2,000 + 500 − 300 = −$1,800, a statement overdraft of $1,800."},{"front":"What mistake should you avoid when studying bank reconciliation that actually reconciles?","back":"Do not post unpresented cheques into the cash book a second time; they are already recorded there."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-21','poa-section-8','How partnerships share ownership','A partnership is a business owned by two or more people carrying on business together for profit. It combines resources and skills but can create disagreements. Ordinary partners commonly have unlimited liability and mutual agency: one partner''s authorised business actions can bind the firm. A sole trader has one owner; a company has a separate legal identity and shareholder ownership. Do not assume every partner has identical duties or liability; read the stated partnership type.',20,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.1","S8.2","S8.3","S8.4"]},"lesson":{"introduction":"A partnership is a business owned by two or more people carrying on business together for profit. It combines resources and skills but can create disagreements. Ordinary partners commonly have unlimited liability and mutual agency: one partner''s authorised business actions can bind the firm. A sole trader has one owner; a company has a separate legal identity and shareholder ownership. Do not assume every partner has identical duties or liability; read the stated partnership type.","objectives":["define a partnership business","state the features of a partnership","give reasons for establishing partnerships","outline the essential components of a partnership agreement"],"sections":[{"title":"Understand the idea","paragraphs":["Partnerships can raise more capital than one person, share workload, bring complementary expertise and spread decision-making. Disadvantages include shared profit, conflict and dependence on other partners'' actions. Distinguish an active partner who works in the firm from a sleeping partner who invests without daily management. A limited partner''s role depends on the legal arrangement; do not treat limited liability as a feature of all partnerships.","A partnership agreement should state capital contributions, profit and loss ratio, drawings rules, interest on capital, interest on drawings, partner salaries, decision-making and arrangements for changes or disputes. In examination questions use the stated agreement. Do not invent a salary or interest rate because it seems fair. Partner salaries and interest on capital are allocations of partnership profit, not ordinary employee expenses.","Compare benefits with the accounting obligation they create. More partners may bring finance and expertise, but each contribution must be separately recorded and the profit-sharing terms agreed. Sharing workload does not justify splitting profits equally if the agreement states another ratio. Treat a partner''s private spending as drawings even if the partner calls it salary informally; use the written terms to identify a genuine profit appropriation."]},{"title":"Worked example","paragraphs":["A baker contributes baking expertise and $30,000, while a second partner provides delivery experience and $20,000. They agree a 3:2 residual profit ratio and a $6,000 salary for the working partner. The agreement, not equal ownership assumptions, governs the appropriation."]},{"title":"Common mistake","paragraphs":["The capital contribution ratio and profit-sharing ratio can differ."]}],"keyPoints":["Record both cash and non-cash capital introduced.","A partner''s loan is distinct from the partner''s capital.","Apply the agreement''s terms rather than assuming equal contributions mean equal shares of profit."],"summary":"A partnership agreement sets out the partners'' contributions, responsibilities and profit-sharing terms. Keep ownership investment distinct from rewards and withdrawals.","check":{"question":"Why record a partnership agreement in writing?","answer":"It states rights and responsibilities clearly and reduces disputes over capital, drawings, remuneration and profit allocation."},"flashcards":[{"front":"Why record a partnership agreement in writing?","back":"It states rights and responsibilities clearly and reduces disputes over capital, drawings, remuneration and profit allocation."},{"front":"What mistake should you avoid when studying how partnerships share ownership?","back":"The capital contribution ratio and profit-sharing ratio can differ."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-22','poa-section-8','Capital accounts and profit appropriation','Record a partner''s cash contribution by debiting bank and crediting that partner''s capital. Non-cash contributions debit the relevant assets at agreed values; liabilities taken over are credited, with net investment credited to capital. Under fixed capital, routine drawings and profit allocations go through separate current accounts. Under fluctuating capital they change the capital accounts themselves.',21,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.5","S8.6","S8.7"]},"lesson":{"introduction":"Record a partner''s cash contribution by debiting bank and crediting that partner''s capital. Non-cash contributions debit the relevant assets at agreed values; liabilities taken over are credited, with net investment credited to capital. Under fixed capital, routine drawings and profit allocations go through separate current accounts. Under fluctuating capital they change the capital accounts themselves.","objectives":["prepare journal entries and ledger accounts to record the capital of partnership","use various methods to share profit/loss among partners","prepare appropriation account of partnerships"],"sections":[{"title":"Understand the idea","paragraphs":["The appropriation account starts with net profit from the income statement. Add interest on drawings, deduct agreed partner salaries and interest on capital, then divide the residual profit or loss in the agreed ratio. These entries distribute profit among owners; they do not change the total operating profit already earned. A partner''s loan interest, where treated as a finance expense under the question''s rules, belongs before appropriation.","For a ratio a:b, divide residual profit by a+b then multiply by each share. If residual profit is negative, allocate that residual loss using the same agreed rule unless otherwise stated. Keep separate columns for partners and check that the total credited allocations, less interest charged on drawings, reconcile to the net profit being shared.","A non-cash contribution needs a complete journal. A contributes equipment valued at $20,000 and inventory $8,000, while the firm takes over the related supplier debt $3,000. Debit equipment $20,000 and inventory $8,000; credit supplier $3,000 and A''s capital $25,000. Total debits and credits are $28,000. B contributes bank $15,000: debit bank and credit B''s capital $15,000. The firm''s net assets and combined capital both increase by $40,000.","Record appropriation through partners'' accounts. For an agreed salary, debit appropriation and credit the partner''s current account. Interest on capital and the residual profit share follow that direction. Interest on drawings reverses it: debit the partner''s current account and credit appropriation. Actual drawings debit the current account and credit bank or the asset withdrawn. Under fixed capital, these routine items do not alter the separate fixed-capital figure.","A residual loss is possible even when the firm earns a profit. Net profit $10,000 less agreed salaries $12,000 leaves residual loss $2,000 if there are no other appropriations. With a 3:2 ratio, debit the partners'' current accounts $1,200 and $800 for that loss. Their net entitlements are salaries less those losses. Check the agreement for any special limitation; do not assume agreed salaries disappear simply because the residual is negative."]},{"title":"Worked example","paragraphs":["Net profit $50,000. Interest on drawings A $500, B $300 gives $50,800 available. Salaries A $10,000, B $6,000 and interest on capital A $3,000, B $2,000 leave residual $29,800. At 3:2, shares are A $17,880 and B $11,920. A''s net allocation is 10,000 + 3,000 + 17,880 − 500 = $30,380; B''s is $19,620; total $50,000."]},{"title":"Common mistake","paragraphs":["Do not divide the whole net profit first and then add salaries and interest: that allocates too much."]}],"keyPoints":["Interest on capital and partners'' salaries are appropriations in these partnership accounts.","Interest on drawings increases the amount available for appropriation.","Share the residual in the agreed ratio."],"summary":"Start the appropriation account with profit available, apply the agreed allowances and share the residual. The residual can be a loss even when the business earned an operating profit.","check":{"question":"Residual profit is $18,000 shared 2:1. What does each partner receive?","answer":"$12,000 and $6,000 respectively."},"flashcards":[{"front":"Residual profit is $18,000 shared 2:1. What does each partner receive?","back":"$12,000 and $6,000 respectively."},{"front":"What mistake should you avoid when studying capital accounts and profit appropriation?","back":"Do not divide the whole net profit first and then add salaries and interest: that allocates too much."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-23','poa-section-8','Current accounts and partnership balance sheets','A partner''s current account tracks the running amount due between the firm and that partner when capital is fixed. Credit opening credit balances, salaries, interest on capital and profit shares. Debit drawings, interest on drawings and losses. An opening debit remains on the debit side. Balance each account separately; do not offset one partner''s debt against another''s credit without showing the detail.',22,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.8","S8.9","S8.10"]},"lesson":{"introduction":"A partner''s current account tracks the running amount due between the firm and that partner when capital is fixed. Credit opening credit balances, salaries, interest on capital and profit shares. Debit drawings, interest on drawings and losses. An opening debit remains on the debit side. Balance each account separately; do not offset one partner''s debt against another''s credit without showing the detail.","objectives":["prepare current account of partners","explain the significance of the brought down balances on partners’ current accounts","prepare balance sheet of partnerships."],"sections":[{"title":"Understand the idea","paragraphs":["A credit current balance means accumulated entitlements exceed drawings: the firm has retained funds belonging to the partner. A debit balance means drawings and charges exceed those entitlements. It reduces the partner''s equity; it is not automatically an operating expense or bad debt. In the balance sheet''s financed-by section show each fixed capital plus or minus current balance.","Prepare the partnership''s assets and external liabilities as for a sole trader. Reconcile net assets with total partners'' equity. Distinguish a partner''s loan from capital when the question provides it: a loan is a liability, while capital is ownership interest. The statement should make clear which balances are fixed capital, current accounts and external obligations.","Complete two partners'' accounts using the earlier $50,000 profit example. A opens current account with credit $2,000 and has net allocation $30,380; drawings $25,000 leave credit $7,380. B opens with debit $1,000, receives net allocation $19,620 and draws $20,000: −1,000 + 19,620 − 20,000 = debit $1,380. In a T account bring down A''s balance on credit and B''s on debit. A debit current balance reduces B''s ownership interest; it is not a new expense.","If A''s fixed capital is $30,000 and B''s $20,000, closing equity is A $37,380 and B $18,620, total $56,000. Independently check: opening combined equity 30,000 + 20,000 + 2,000 − 1,000 = $51,000; add net profit $50,000 and deduct total drawings $45,000: closing $56,000. A balance sheet with net non-current assets $60,000, current assets $25,000, current liabilities $9,000 and long-term loan $20,000 gives the same net assets $56,000."]},{"title":"Worked example","paragraphs":["A has opening current credit $2,000, salary $6,000, interest on capital $1,000, profit share $8,000, drawings $12,000 and interest on drawings $500. Closing current = 2,000 + 6,000 + 1,000 + 8,000 − 12,000 − 500 = $4,500 credit. Fixed capital $30,000 plus current $4,500 gives A''s equity $34,500."]},{"title":"Common mistake","paragraphs":["Drawings are debited to current accounts under fixed capital, not deducted as a trading expense."]}],"keyPoints":["Credit current accounts with salaries, interest on capital and profit shares.","Debit drawings, interest on drawings and loss shares.","A debit current-account balance reduces that partner''s net interest."],"summary":"With fixed capital, the current account records the partner''s share of profit, allowances and drawings. Reconcile all partners'' equity with the partnership''s net assets.","check":{"question":"Partner B has fixed capital $20,000 and current debit $1,200. Total equity?","answer":"$18,800: deduct the debit current balance from fixed capital."},"flashcards":[{"front":"Partner B has fixed capital $20,000 and current debit $1,200. Total equity?","back":"$18,800: deduct the debit current balance from fixed capital."},{"front":"What mistake should you avoid when studying current accounts and partnership balance sheets?","back":"Drawings are debited to current accounts under fixed capital, not deducted as a trading expense."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-24','poa-section-9','Companies, cooperatives and member organisations','A limited liability company has a separate legal identity, continuity and ownership divided into shares. Shareholders generally risk their investment rather than all personal property. A private company restricts share transfers and public offers in the relevant way; a public company can raise funds from the public subject to its rules. Advantages include access to capital and continuity; disadvantages include formation costs, reporting requirements and separation of ownership from control.',23,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":25,"section":9,"objectiveCodes":["S9.1","S9.2","S9.3","S9.4","S9.5"]},"lesson":{"introduction":"A limited liability company has a separate legal identity, continuity and ownership divided into shares. Shareholders generally risk their investment rather than all personal property. A private company restricts share transfers and public offers in the relevant way; a public company can raise funds from the public subject to its rules. Advantages include access to capital and continuity; disadvantages include formation costs, reporting requirements and separation of ownership from control.","objectives":["identify the essential features of limited liability companies, co- operatives and non-profit organisations","identify the types of limited liability companies, co-operatives and non- profit organisations","outline the advantages and disadvantages of a limited liability company","describe the various methods of raising capital available to limited liability companies and co- operatives","identify the various types of shares and the rights of the owners of each type of share"],"sections":[{"title":"Understand the idea","paragraphs":["Ordinary shareholders normally have voting rights and a variable residual return. Preference shares normally receive a specified dividend before ordinary dividends, subject to their terms. Cumulative preference shares may carry arrears forward. Shares are equity. Debentures and bank loans are debt: interest is a finance cost, and principal remains repayable. A debenture holder is a lender, not automatically a voting owner.","Cooperatives are member-owned organisations such as credit unions and agricultural cooperatives, emphasising member benefit and democratic control. They can raise member share capital and borrowing. Non-profit clubs and societies organise services rather than distributing business profits to owners. Distinguish share capital, reserves, retained earnings, member funds and liabilities instead of labelling every source of money as profit.","Identify the organisation from its purpose and ownership, not just its size. A credit union provides financial services to members; an agricultural cooperative may help members purchase inputs or market produce; a sports club provides activities for members. A company belongs to shareholders. Cooperative voting commonly follows one member, one vote rather than rewarding the largest investment, while company voting depends on the share rights. Apply the particular rules supplied in an exercise.","Share rights require careful reading. Ordinary shares normally bear the residual risk and receive dividends only when declared. Preference terms can specify a prior fixed-rate dividend, whether unpaid dividends accumulate, whether holders participate further, and repayment priorities. ''Cumulative'' means an omitted entitlement may be carried forward under the terms; ''non-cumulative'' does not automatically create such arrears. Do not assume every preference share has exactly the same voting or dividend rights.","Consider financing consequences. Issuing shares raises equity without a contractual interest charge, but can affect control and the return available per existing share. Borrowing avoids issuing ownership but requires the agreed interest and repayment. Retaining earnings keeps funds invested in the business; the reserve or retained-earnings figure is not necessarily cash sitting in a separate bank account. Explain both the source of funds and the obligation or ownership interest it creates."]},{"title":"Worked example","paragraphs":["A company issues $100,000 of ordinary shares and borrows $40,000 by debentures. Bank increases $140,000; share capital increases $100,000; debenture liability increases $40,000. A 6% debenture carries annual interest $2,400 under the stated terms, regardless of whether an ordinary dividend is declared."]},{"title":"Common mistake","paragraphs":["Limited liability does not mean the company itself has no debts or can ignore creditors."]}],"keyPoints":["Shareholders own shares in a company.","Cooperatives are owned and governed by their members.","A club''s accumulated fund serves a different purpose from a sole trader''s capital."],"summary":"The organisation''s purpose and ownership determine the names used for capital, returns and decision-making. Apply the right terms to companies, cooperatives and member organisations.","check":{"question":"Does a debenture issue increase share capital?","answer":"No. It raises borrowed funds and creates a liability."},"flashcards":[{"front":"Does a debenture issue increase share capital?","back":"No. It raises borrowed funds and creates a liability."},{"front":"What mistake should you avoid when studying companies, cooperatives and member organisations?","back":"Limited liability does not mean the company itself has no debts or can ignore creditors."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-25','poa-section-9','Share issues, dividends and final accounts','On a cash issue at nominal value, debit bank and credit the relevant share capital. If a premium is specified, split the proceeds between nominal share capital and share premium. Record a cash debenture issue by debiting bank and crediting debentures. Follow the question''s issue terms; do not invent a premium or treat share proceeds as sales revenue.',24,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":25,"section":9,"objectiveCodes":["S9.6","S9.7","S9.8","S9.9","S9.10"]},"lesson":{"introduction":"On a cash issue at nominal value, debit bank and credit the relevant share capital. If a premium is specified, split the proceeds between nominal share capital and share premium. Record a cash debenture issue by debiting bank and crediting debentures. Follow the question''s issue terms; do not invent a premium or treat share proceeds as sales revenue.","objectives":["prepare journal entries to record the issue of shares and debentures","calculate dividend payments for various types of shares","appropriate profits between dividends and reserves;","prepare the final accounts of limited liability companies and co-operatives","analyse performance and position using ratios"],"sections":[{"title":"Understand the idea","paragraphs":["A percentage preference dividend is normally calculated on the stated nominal preference capital, not on profit or market value. An ordinary dividend may be given per share or as a percentage of nominal capital; identify the base carefully. Appropriation allocates available profit between dividends, reserves and retained earnings. Debenture interest is an expense before profit appropriation. A transfer to reserve reallocates equity; it is not an operating cost or a separate cash payment.","Prepare the income statement with the appropriate expenses, then the distribution or appropriation and the balance sheet. Equity contains share capital and reserves/retained earnings; loans and debentures are liabilities. For a cooperative, show the surplus and its distribution using the given rules. Apply profitability and liquidity ratios using the correct organisation''s capital and stated definitions, then explain what the numbers imply.","Work an issue with two components. A company issues 10,000 ordinary $2 shares at $2.50 each for cash. Proceeds are $25,000: debit bank $25,000, credit ordinary share capital $20,000 and credit share premium $5,000. Separately it issues $30,000 of 8% debentures at par: debit bank and credit debentures $30,000. Annual interest on those debentures is $2,400 for a full year under those terms. Neither issue is sales income.","For cumulative preference shares, show the year calculation and any stated arrears separately. Preference capital $50,000 at 6% has a full-year entitlement $3,000. If one prior year is explicitly unpaid and the terms require it to be covered before the current ordinary distribution, $6,000 is needed for the two years. A non-cumulative question would not automatically add the prior year''s missed amount. Do not infer unpaid years that are absent from the facts.","A complete company example links profit to equity. Net sales $200,000 less cost of sales $120,000 gives gross profit $80,000. Operating expenses $50,000 and debenture interest $4,000 leave profit $26,000 before any tax specified; this example supplies none. Add opening retained earnings $8,000: $34,000 is available. Preference dividend $4,000, ordinary dividend $6,000 and transfer to general reserve $5,000 leave closing retained earnings $19,000. The year''s profit retained after dividends is $16,000, split between the $5,000 reserve transfer and an $11,000 increase in retained earnings.","Finish that company''s balance sheet: net non-current assets $100,000 and current assets $60,000 less current liabilities $12,000 and debentures $40,000 give net assets $108,000. Equity is ordinary capital $60,000, preference capital $20,000, opening general reserve $4,000 plus current transfer $5,000, and closing retained earnings $19,000: total $108,000. Assume the dividends in this example were paid and are already reflected in bank. If a question identifies a recognised unpaid dividend liability, show it under its stated treatment rather than assuming payment.","For a cooperative, separate earning the surplus from distributing it. Income $90,000 less operating costs and stated finance costs $60,000 gives surplus $30,000. Suppose its stated rules allocate reserve $6,000, member-share dividend $4,000 and patronage refund $8,000. Undistributed surplus is $12,000. If the patronage refund is based on qualifying member purchases totalling $160,000, the refund rate is 8,000/160,000 = 5%; a member with purchases $5,000 receives $250. The dividend base and patronage base are different.","A cooperative position check might show net assets $80,000 financed by member shares $50,000, reserve $18,000 and undistributed surplus $12,000. Current assets $35,000 and current liabilities $14,000 give current ratio 2.5:1; with inventory $14,000, acid test is 21,000/14,000 = 1.5:1. Explain these figures using the cooperative''s activities. A large reserve does not remove the need to collect debts or keep sufficient cash for payments."]},{"title":"Worked example","paragraphs":["Preference capital $40,000 at 5% gives dividend $2,000. Ordinary capital comprises 30,000 $1 shares; a dividend of $0.10 each is $3,000. Profit available $12,000 less preference dividend $2,000, ordinary dividend $3,000 and reserve transfer $1,500 leaves $5,500 retained for the period. Opening retained earnings must be added if the question asks for the closing balance."]},{"title":"Common mistake","paragraphs":["Do not deduct dividends when calculating gross profit or operating profit."]}],"keyPoints":["Share premium is the issue price above nominal value.","Check the rights attached to preference and ordinary shares.","Reconcile profit, transfers and dividends to the closing retained-profit balance."],"summary":"Separate share capital, share premium, reserves and retained profit. Dividends distribute profit to shareholders; issuing shares raises finance from them.","check":{"question":"10,000 shares of $2 nominal value receive a 6% dividend. Total dividend?","answer":"10,000 × $2 × 6% = $1,200."},"flashcards":[{"front":"10,000 shares of $2 nominal value receive a 6% dividend. Total dividend?","back":"10,000 × $2 × 6% = $1,200."},{"front":"What mistake should you avoid when studying share issues, dividends and final accounts?","back":"Do not deduct dividends when calculating gross profit or operating profit."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-26','poa-section-9','Receipts and payments for clubs','A receipts and payments account summarises actual money received and paid by a non-profit organisation over a period. Begin with opening cash and bank balances, add all receipts and deduct all payments to find closing cash and bank. Include capital and revenue cash movements, even if they relate to another accounting period.',25,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":26,"section":9,"objectiveCodes":["S9.11"]},"lesson":{"introduction":"A receipts and payments account summarises actual money received and paid by a non-profit organisation over a period. Begin with opening cash and bank balances, add all receipts and deduct all payments to find closing cash and bank. Include capital and revenue cash movements, even if they relate to another accounting period.","objectives":["prepare receipts and payment accounts for non-profit organisations"],"sections":[{"title":"Understand the idea","paragraphs":["Typical receipts include subscriptions, donations, event takings and proceeds from selling equipment. Payments include rent, utilities, equipment purchases and event costs. A depreciation charge does not appear because no money is paid when depreciation is recorded. An unpaid bill and subscriptions owing also do not appear until cash moves. Keep a supporting schedule so the source of each total can be traced.","An income and expenditure account is different: it adjusts revenue and expenses for the period and reports surplus or deficit. The current syllabus requires preparation of the receipts and payments account here, while learners should still recognise the purpose of income and expenditure. Never describe a closing cash balance as the club''s surplus without checking accruals and capital transactions.","Use two sides if a question asks for an account format: opening positive cash/bank and receipts on the debit side; payments and closing positive balances on the credit side. Alternatively use a clearly labelled cash-summary format if permitted. A subscription receipt belongs in the account whenever paid, even if it settles last year''s arrears or pays next year''s subscription early. The timing of the cash, rather than the subscription period, controls this account.","Complete a club account with mixed cash items. Opening bank $2,000; subscriptions received $12,000, of which $1,000 is for last year and $2,000 for next year; fundraising takings $4,000; equipment-sale proceeds $500. Total funds available are $18,500. Payments are rent $3,000, equipment purchase $5,000, event costs $2,000 and utilities $1,200: total $11,200. Closing bank is $7,300. Include all $12,000 of subscriptions and both equipment cash amounts. Exclude unpaid bills and depreciation.","A club can have rising cash and still a deficit on an accrual basis, or falling cash and a surplus. A loan or equipment sale brings in cash without being ordinary income for the period; an equipment purchase uses cash without being fully charged as the period''s expense. For this syllabus, practise preparing receipts and payments and explaining the purpose of income and expenditure. Do not relabel the $7,300 closing bank as a surplus."]},{"title":"Worked example","paragraphs":["A youth club opens with bank $3,000, collects subscriptions $9,000 and donations $2,000, pays equipment $4,500 and expenses $5,000. Closing bank = 3,000 + 9,000 + 2,000 − 4,500 − 5,000 = $4,500. The equipment payment is included in full; depreciation is excluded."]},{"title":"Common mistake","paragraphs":["Opening cash is a balance brought forward, not income earned this year."]}],"keyPoints":["Include capital receipts and payments in the cash account.","Adjust subscriptions for amounts owing and paid in advance.","Surplus increases the accumulated fund; a deficit reduces it."],"summary":"A receipts and payments account follows cash. An income and expenditure account follows the period''s income and expenses, including non-cash adjustments.","check":{"question":"A club owes $600 for electricity at year end. Does the unpaid amount enter receipts and payments?","answer":"No. Record the payment when it occurs; the unpaid expense matters to accrual accounts, not this cash summary."},"flashcards":[{"front":"A club owes $600 for electricity at year end. Does the unpaid amount enter receipts and payments?","back":"No. Record the payment when it occurs; the unpaid expense matters to accrual accounts, not this cash summary."},{"front":"What mistake should you avoid when studying receipts and payments for clubs?","back":"Opening cash is a balance brought forward, not income earned this year."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-27','poa-section-10','Manufacturing accounts and unit cost','A manufacturer converts raw materials into finished goods. Direct materials can be traced to a product, such as flour in bread. Direct labour works on the product. Other traceable direct expenses may also be included. Indirect factory costs, such as a supervisor''s salary, factory rent and machinery depreciation, are overheads. Office salaries and selling expenses are normally excluded from factory production cost.',26,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.1","S10.2","S10.3","S10.4"]},"lesson":{"introduction":"A manufacturer converts raw materials into finished goods. Direct materials can be traced to a product, such as flour in bread. Direct labour works on the product. Other traceable direct expenses may also be included. Indirect factory costs, such as a supervisor''s salary, factory rent and machinery depreciation, are overheads. Office salaries and selling expenses are normally excluded from factory production cost.","objectives":["distinguish between direct and indirect costs","prepare manufacturing accounts","calculate unit cost of items produced","prepare final accounts for a manufacturing concern"],"sections":[{"title":"Understand the idea","paragraphs":["Raw materials consumed = opening raw materials + net raw material purchases + relevant carriage − closing raw materials. Prime cost = direct materials consumed + direct labour + direct expenses. Add factory overheads, add opening work in progress and deduct closing work in progress to find cost of production. Work in progress is partly completed production; closing work not yet finished must remain an asset rather than all being charged to completed goods.","Unit production cost = cost of completed production ÷ completed units. Transfer cost of production to the trading section. Cost of finished goods sold = opening finished goods + cost of production − closing finished goods, adjusted for any other stated items. Show raw materials, work in progress and finished goods separately as appropriate in the balance sheet. Production cost is not automatically the selling price.","Keep three inventories distinct. Raw materials have not yet entered production; work in progress has begun but is unfinished; finished goods are complete and await sale. Raw-material closing inventory reduces materials consumed. Closing work in progress reduces the cost allocated to completed production. Closing finished goods reduces the cost of completed goods sold. Each also has a corresponding closing asset value. Moving one figure into the wrong stage can distort several subtotals.","Extend the worked manufacturing account into final accounts. Cost of production is $57,000. Opening finished goods $8,000 plus production $57,000 less closing finished goods $10,000 gives cost of sales $55,000. With sales $90,000, gross profit is $35,000. Office costs $9,000 and selling costs $6,000 give net profit $20,000, assuming no other items. Closing inventories in the balance sheet total raw materials $6,000 + WIP $7,000 + finished goods $10,000 = $23,000.","Apportion shared costs using the stated evidence. Total rent is $12,000 and 75% relates to factory space: factory overhead is $9,000 and office expense $3,000. A factory supervisor''s pay is indirect labour, while a machine operator''s pay traceable to production is direct labour under these facts. Classify before adding. The full $12,000 rent is included once across the accounts, not $12,000 in manufacturing plus another $3,000 in profit and loss."]},{"title":"Worked example","paragraphs":["Opening raw materials $5,000 + purchases $28,000 + carriage $2,000 − closing $6,000 = materials consumed $29,000. Add direct wages $20,000: prime cost $49,000. Add factory overhead $11,000, opening WIP $4,000, less closing WIP $7,000: production cost $57,000. For 3,000 completed units, unit cost is $19."]},{"title":"Common mistake","paragraphs":["Closing work in progress is deducted; opening work in progress is added. Do not reverse them."]}],"keyPoints":["Materials consumed + direct labour + direct expenses = prime cost.","Add factory overheads and opening work in progress, then deduct closing work in progress.","Unit cost = completed production cost ÷ completed units."],"summary":"Trace production from raw materials through work in progress to finished goods. Calculate the cost of completed production before transferring it to the trading account.","check":{"question":"Where does factory-machine depreciation go: factory overhead or selling expense?","answer":"Factory overhead, because it supports production."},"flashcards":[{"front":"Where does factory-machine depreciation go: factory overhead or selling expense?","back":"Factory overhead, because it supports production."},{"front":"What mistake should you avoid when studying manufacturing accounts and unit cost?","back":"Closing work in progress is deducted; opening work in progress is added. Do not reverse them."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-28','poa-section-10','Costing and setting prices','Cost-plus pricing adds an intended profit amount to a relevant cost. A mark-up of r% on cost gives selling price = cost × (1 + r/100). A profit margin of m% of selling price instead gives selling price = cost ÷ (1 − m/100). Identify the denominator; the same numeric percentage produces different prices under these two methods.',27,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.5"]},"lesson":{"introduction":"Cost-plus pricing adds an intended profit amount to a relevant cost. A mark-up of r% on cost gives selling price = cost × (1 + r/100). A profit margin of m% of selling price instead gives selling price = cost ÷ (1 − m/100). Identify the denominator; the same numeric percentage produces different prices under these two methods.","objectives":["apply basic costing principles"],"sections":[{"title":"Understand the idea","paragraphs":["Absorption costing includes an appropriate share of production overhead in product cost, alongside direct costs. If overhead is allocated by labour hours, overhead rate = budgeted factory overhead ÷ budgeted labour hours. Multiply the rate by the hours used by each product. Choose the base given in the question rather than automatically dividing by units where products use resources differently.","A price should cover the intended costs, but customers, competitors, waste, capacity and demand also matter. Distinguish factory production cost from full business cost: office and selling costs still have to be covered by overall revenue. Explain the basis of a recommendation and show the cost calculations, rather than claiming any cost-plus price guarantees a profit.","Do a reasonableness check after pricing. Cost $80 and 25% mark-up gives selling price $100, profit $20 and margin 20%. Cost $80 and 25% margin gives price $106.67 approximately, because cost is 75% of selling price. Use enough precision for the requested rounding. A phrase such as ''25% profit'' is ambiguous without a base; in a real plan clarify it, and in an examination follow the exact wording and supplied convention.","Fixed and variable costs answer a different question from direct and indirect. Factory rent may remain fixed in total over the relevant output range, while its cost per unit falls as output rises. Materials commonly vary with units produced and can also be direct. A supervisor''s fixed salary can be indirect. Do not assume ''fixed'' means non-current asset or ''indirect'' means the cost can be ignored when calculating production cost."]},{"title":"Worked example","paragraphs":["Factory overhead $24,000 ÷ 6,000 labour hours = $4 per hour. A product needs materials $12, direct labour $8 and two labour hours of overhead $8: absorbed production cost $28. A 25% mark-up gives $35. A 25% margin would require $28/0.75 = $37.33 approximately."]},{"title":"Common mistake","paragraphs":["Do not include the same overhead once in a unit cost and again as an additional markup cost."]}],"keyPoints":["A direct cost can be traced to a product or job.","Allocate shared costs on a stated, reasonable basis.","Check whether a quoted percentage is a mark-up on cost or a margin on selling price."],"summary":"Classify each cost according to the decision being made. Direct and indirect describe traceability; fixed and variable describe behaviour as output changes.","check":{"question":"Cost is $80 and desired margin is 20%. Selling price?","answer":"$80/(1 − 0.20) = $100; profit $20 is 20% of selling price."},"flashcards":[{"front":"Cost is $80 and desired margin is 20%. Selling price?","back":"$80/(1 − 0.20) = $100; profit $20 is 20% of selling price."},{"front":"What mistake should you avoid when studying costing and setting prices?","back":"Do not include the same overhead once in a unit cost and again as an additional markup cost."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-29','poa-section-10','FIFO, LIFO and average inventory cost','Inventory valuation assigns costs to goods issued and goods remaining. FIFO, first in first out, issues the oldest cost layers first. LIFO, last in first out, issues the newest layers first. Average cost uses a weighted cost per unit; check whether the question requires periodic weighted average or moving average after each receipt. These are cost-flow assumptions and do not necessarily describe the physical movement of goods.',28,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.6","S10.7"]},"lesson":{"introduction":"Inventory valuation assigns costs to goods issued and goods remaining. FIFO, first in first out, issues the oldest cost layers first. LIFO, last in first out, issues the newest layers first. Average cost uses a weighted cost per unit; check whether the question requires periodic weighted average or moving average after each receipt. These are cost-flow assumptions and do not necessarily describe the physical movement of goods.","objectives":["list methods of inventory valuation","calculate the value of closing inventory using either FIFO or LIFO; AVCO."],"sections":[{"title":"Understand the idea","paragraphs":["Keep a stock record with date, receipts, issues and balance. Under FIFO or LIFO retain quantities and unit costs in separate layers. Do not sell or issue more units than are available at that date. Moving average cost = value available after a receipt ÷ quantity available after that receipt; subsequent issues use that rate until another receipt. Keep enough precision during calculations and round final money consistently.","When purchase prices rise, FIFO usually leaves newer, higher-cost closing stock and gives lower cost of sales and higher profit than LIFO for the same transactions. Weighted average normally lies between them. The syllabus includes LIFO for learning and examination calculations; this does not imply it is permitted by every financial reporting framework. Closing inventory must also be assessed under the valuation instructions given.","A dated stock record shows why moving average needs recalculation after receipts. Receive 10 units at $4, then 20 at $7: 30 units costing $180, average $6. Issue 12: cost $72, leaving 18 units valued $108. Receive another 12 at $9: now 30 units costing $216, average $7.20. Issue 10: cost $72, leaving 20 units valued $144. Total receipts $288 equal total issue costs $144 plus closing value $144.","Using those dates, FIFO gives first issue 10×4 + 2×7 = $54; then the second issue uses 10×7 = $70. Closing layers are 8×7 + 12×9 = $164. LIFO gives first issue 12×7 = $84; second issue after the last receipt uses 10×9 = $90. Closing layers are 10×4 + 8×7 + 2×9 = $114. Check each method against the same receipts total $288. Never use a later receipt to cost an earlier issue under a dated perpetual stock record.","Periodic weighted average answers a different timing question: total cost available divided by total units available for the period. In that same example all 42 received units cost $288, so periodic average is $6.857142...; closing 20 units are about $137.14. It differs from the $144 moving-average closing value because moving average costs each issue using only what is available then. Label the method and avoid changing methods halfway through a stock card."]},{"title":"Worked example","paragraphs":["Buy 10 units at $5 and 10 at $7, then issue 12. FIFO issue cost = 10×5 + 2×7 = $64; remaining 8×7 = $56. LIFO issue cost = 10×7 + 2×5 = $80; remaining 8×5 = $40. Weighted average = $120/20 = $6; issue $72 and closing $48. Total issue cost plus closing value is always $120 here."]},{"title":"Common mistake","paragraphs":["A simple average of prices is wrong when quantities differ. Weight each price by its quantity."]}],"keyPoints":["FIFO issues the earliest costs first; LIFO issues the latest costs first.","Moving average recalculates the unit cost after a receipt.","The pricing method describes cost flow and need not describe the physical movement of stock."],"summary":"Keep a dated inventory record and apply one stated issue-pricing method consistently. Reconcile the quantity and value left after every issue.","check":{"question":"Buy 5 units at $4 and 15 at $8. Weighted average cost?","answer":"(5×4 + 15×8)/20 = $7 per unit."},"flashcards":[{"front":"Buy 5 units at $4 and 15 at $8. Weighted average cost?","back":"(5×4 + 15×8)/20 = $7 per unit."},{"front":"What mistake should you avoid when studying fifo, lifo and average inventory cost?","back":"A simple average of prices is wrong when quantities differ. Weight each price by its quantity."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-30','poa-section-11','Payments and payroll evidence','Businesses pay employees, suppliers and service providers by cash, cheque, transfer, standing order, direct debit and point-of-sale methods. A standing order is normally an instruction to pay a set amount regularly; a direct debit authorises the recipient to collect under agreed terms. Choose a method that suits security, timing, records and the recipient''s access. Keep authorisation and proof of payment.',29,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.1","S11.2","S11.4","S11.5"]},"lesson":{"introduction":"Businesses pay employees, suppliers and service providers by cash, cheque, transfer, standing order, direct debit and point-of-sale methods. A standing order is normally an instruction to pay a set amount regularly; a direct debit authorises the recipient to collect under agreed terms. Choose a method that suits security, timing, records and the recipient''s access. Keep authorisation and proof of payment.","objectives":["list methods of payment","identify basic source documents of the payroll","identify main accounting software used for payroll","distinguish between voluntary and statutory deductions"],"sections":[{"title":"Understand the idea","paragraphs":["Payroll starts with employee records, agreed rates, time cards, time books or electronic attendance. Check ordinary hours, overtime, leave and approved deductions. Payroll software and spreadsheets can calculate earnings, deductions and reports, but records must be checked for incorrect rates, duplicated employees and unauthorised changes. Separate preparation, authorisation and payment where possible.","Statutory deductions are required under applicable law, such as income tax or social security. Voluntary deductions are authorised by the employee, such as a savings contribution or loan repayment. Rates and thresholds vary by territory and date; an exercise should supply them or use verified current rules. In this course''s calculators, entered deductions are exercise values and are not asserted to be current legal tax calculations.","The syllabus gives QuickBooks and Peachtree Accounting as examples of payroll or accounting software names. Recognise them as syllabus examples rather than assuming a particular current version has every feature in every territory. In an explanation, connect software to employee records, earnings calculations, deduction schedules, payslips and audit trails. A spreadsheet can also support a small exercise, but the user must create, protect and check the formulas.","Match payroll documents to their role. A time card or electronic clock record supplies attendance; an approved employee record supplies pay rate and identity; an overtime authorisation supports additional hours; an earnings record summarises a person''s pay over time; a payslip explains the current gross pay, deductions and net pay. None independently authorises an invented employee or a changed bank account. Keep the pay period and approval references visible."]},{"title":"Worked example","paragraphs":["A time record shows 40 ordinary hours and 5 approved overtime hours. Before calculating pay, confirm the rate, overtime multiplier and which deductions apply. A missing approval is a control problem even if the arithmetic is correct."]},{"title":"Common mistake","paragraphs":["Do not copy a statutory deduction rate from another country or an old past paper into a current real payroll."]}],"keyPoints":["Match payments to supporting documents and approvals.","Time records, rates and deductions support the payroll calculation.","Use the rates supplied in a question rather than assuming current statutory rates."],"summary":"Payment and payroll records should show what was approved, what was paid and how the amount was calculated. Protect employee information and keep an audit trail.","check":{"question":"Is an employee''s authorised savings-club deduction statutory or voluntary?","answer":"Voluntary. It follows the employee''s authorisation rather than an automatic legal requirement."},"flashcards":[{"front":"Is an employee''s authorised savings-club deduction statutory or voluntary?","back":"Voluntary. It follows the employee''s authorisation rather than an automatic legal requirement."},{"front":"What mistake should you avoid when studying payments and payroll evidence?","back":"Do not copy a statutory deduction rate from another country or an old past paper into a current real payroll."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-31','poa-section-11','Calculate gross pay, deductions and net pay','Gross pay is earnings before deductions. Time-rate ordinary pay = ordinary hours × hourly rate. Overtime pay = overtime hours × hourly rate × overtime multiplier. Add any stated bonus, commission or piecework earnings. Piecework pay uses units produced × rate per unit. If salary is given for a month, do not multiply it by hours unless the question requires a conversion.',30,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.3","S11.6"]},"lesson":{"introduction":"Gross pay is earnings before deductions. Time-rate ordinary pay = ordinary hours × hourly rate. Overtime pay = overtime hours × hourly rate × overtime multiplier. Add any stated bonus, commission or piecework earnings. Piecework pay uses units produced × rate per unit. If salary is given for a month, do not multiply it by hours unless the question requires a conversion.","objectives":["prepare spreadsheet to arrive at net pay amounts after deductions","calculate employees’ earnings"],"sections":[{"title":"Understand the idea","paragraphs":["Net pay = gross pay − total employee deductions. Calculate each deduction on its stated base: some may use gross earnings, a taxable amount after allowances, or a fixed sum. Employer contributions are a separate employer cost unless the question explicitly includes them in employee deductions. They should not automatically reduce net pay.","In a payroll spreadsheet, give each input a clear column, use formulas for ordinary pay, overtime, gross, deductions and net, and total the columns. Validate non-negative hours and sensible rates. Keep employee identifiers and a pay-period date. Check that gross minus employee deductions equals net for each person and for the payroll total. Review unusual values before payment; a formula copied into the wrong row can still produce a plausible number.","Build a spreadsheet row in the order of the calculation. If B2 is ordinary hours, C2 hourly rate, D2 overtime hours, E2 overtime multiplier and F2 bonus, gross pay in G2 can be =B2*C2+D2*C2*E2+F2. If H2 is an exercise deduction rate, I2 fixed statutory deduction and J2 voluntary deduction, total deductions in K2 can be =G2*H2+I2+J2 and net pay in L2 =G2-K2. These formulas assume H2 is entered as a percentage and all percentage deductions use gross; change the formula when the stated base differs.","Work a second payroll row and total both employees. Employee B works 35 hours at $400 plus 4 overtime hours at double time: ordinary $14,000 and overtime $3,200 give gross $17,200. Exercise deductions of 4% of gross $688 plus authorised savings $300 total $988, so net pay is $16,212. Combined with the worked example''s gross $25,500, deductions $3,775 and net $21,725, payroll totals are gross $42,700, deductions $4,763 and net $37,937. Check 42,700 − 4,763 = 37,937.","If commission is 3% of qualifying sales $80,000, earnings from commission are $2,400. Piecework at $150 for each of 60 accepted units earns $9,000 under those terms. A fixed monthly salary $48,000 is already a period amount. State whether commission or piecework is added to basic pay or replaces it: the question must supply that relationship. Deduction bases, allowances and overtime rules also come from the stated exercise, not an assumed legal rate."]},{"title":"Worked example","paragraphs":["Ordinary 40 hours at $500 = $20,000. Overtime 6 hours at time-and-a-half = 6×500×1.5 = $4,500. Bonus $1,000 gives gross $25,500. Exercise deductions: 5% of gross $1,275, fixed $2,000 and savings $500. Total deductions $3,775; net pay $21,725. These are illustrative exercise deductions, not a statement of current statutory rates."]},{"title":"Common mistake","paragraphs":["Overtime at time-and-a-half is 1.5 times the ordinary rate, not the ordinary rate plus another 1.5 times."]}],"keyPoints":["Keep basic hours and overtime hours separate.","Gross pay may include commission, bonuses or piecework earnings.","Net pay = gross pay − total employee deductions."],"summary":"Calculate gross earnings first, then apply each deduction to its stated base. Net pay is what remains for the employee after deductions.","check":{"question":"Gross pay $30,000 less deductions $4,800. Net pay?","answer":"$25,200."},"flashcards":[{"front":"Gross pay $30,000 less deductions $4,800. Net pay?","back":"$25,200."},{"front":"What mistake should you avoid when studying calculate gross pay, deductions and net pay?","back":"Overtime at time-and-a-half is 1.5 times the ordinary rate, not the ordinary rate plus another 1.5 times."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-32','poa-section-11','Six-month cash flow forecasts','A cash flow projection estimates when cash will enter and leave the business. It helps an entrepreneur identify shortfalls early. For each month, opening cash + cash inflows − cash outflows = closing cash. The next month''s opening equals the previous month''s closing. Include owner investment, loans and grants as inflows when actually received, and asset purchases or loan principal as outflows when paid.',31,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.7"]},"lesson":{"introduction":"A cash flow projection estimates when cash will enter and leave the business. It helps an entrepreneur identify shortfalls early. For each month, opening cash + cash inflows − cash outflows = closing cash. The next month''s opening equals the previous month''s closing. Include owner investment, loans and grants as inflows when actually received, and asset purchases or loan principal as outflows when paid.","objectives":["prepare cash flow projections within a six-month period;"],"sections":[{"title":"Understand the idea","paragraphs":["Separate cash sales from credit collections. If customers pay a month after sale, January credit sales become February collections under that assumption. Likewise a purchase made on credit is paid in the month specified by supplier terms. Depreciation is not a cash payment. Profit is not an additional inflow to add on top of sales receipts: that would count the same activity twice.","Lay out six monthly columns with receipts, payments, net flow, opening and closing cash. Use realistic timing and state assumptions about demand, late payments and costs. A negative closing balance indicates a financing need or a need to change timing; it is not automatically permission to overdraw. Explore earlier collection, delayed non-essential spending or suitable finance, and assess the cost and feasibility of each.","Work all six monthly balances in one linked forecast. Opening January cash is $5,000. Cash inflows for January to June are $12,000, $10,000, $16,000, $18,000, $20,000 and $22,000. Outflows are $14,000, $15,000, $13,000, $16,000, $18,000 and $19,000. Net monthly flows are −$2,000, −$5,000, +$3,000, +$2,000, +$2,000 and +$3,000. Closing balances are January $3,000; February −$2,000; March $1,000; April $3,000; May $5,000; June $8,000.","Check that forecast by totals: six-month inflows $98,000 less outflows $95,000 give net inflow $3,000; opening $5,000 plus $3,000 gives June closing $8,000. The February shortfall still needs action even though June is positive. If a $4,000 loan is received in February and no interest or repayment falls within the forecast under the stated assumptions, all February-to-June closings rise $4,000. It changes finance and cash, not sales or operating profit.","Create receipt timings separately from the sales budget. If sales are 40% cash and 60% collected the next month, January sales $20,000 produce January cash $8,000 and February collections $12,000. If December credit sales still to collect are $9,000, January sales-related receipts are $17,000. Similarly, identify supplier payment terms before scheduling purchases. This prevents using the same month''s revenue as its receipts without checking the credit terms."]},{"title":"Worked example","paragraphs":["January opens $5,000, receives $12,000 and pays $14,000: closing $3,000. February opens $3,000, receives $10,000 and pays $15,000: closing −$2,000. The business must address the projected $2,000 shortfall before payments fall due. A new $4,000 loan received in February would make its closing cash $2,000 but also create a debt."]},{"title":"Common mistake","paragraphs":["Do not restart every month with the original opening cash balance."]}],"keyPoints":["Opening cash + receipts − payments = closing cash.","Credit sales enter the forecast when customers are expected to pay.","Depreciation is an expense but does not create a cash payment in the forecast."],"summary":"A cash forecast follows the timing of receipts and payments. Carry each month''s closing balance into the next month and investigate shortages before they occur.","check":{"question":"Is depreciation included as a cash outflow?","answer":"No. The equipment payment is a cash movement; depreciation allocates cost without a new cash payment."},"flashcards":[{"front":"Is depreciation included as a cash outflow?","back":"No. The equipment payment is a cash movement; depreciation allocates cost without a new cash payment."},{"front":"What mistake should you avoid when studying six-month cash flow forecasts?","back":"Do not restart every month with the original opening cash balance."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-33','poa-section-11','Sales budgets, production budgets and a business plan','A sales budget estimates units sold and sales value. Sales value = budgeted units × selling price. A production budget links sales demand to stock targets: production units = sales units + desired closing finished goods − opening finished goods. The closing inventory of one month becomes the next month''s opening inventory. Production is not always equal to sales.',32,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":30,"section":11,"objectiveCodes":["S11.8","S11.9"]},"lesson":{"introduction":"A sales budget estimates units sold and sales value. Sales value = budgeted units × selling price. A production budget links sales demand to stock targets: production units = sales units + desired closing finished goods − opening finished goods. The closing inventory of one month becomes the next month''s opening inventory. Production is not always equal to sales.","objectives":["prepare sales and production budgets for a three-month period","use accounting knowledge and skills to prepare a simple business plan"],"sections":[{"title":"Understand the idea","paragraphs":["For a three-month plan, calculate quantities first, then materials, labour and overhead needs. Materials needed = production × material per unit; adjust for opening and desired closing raw materials to find purchases. State assumptions about selling prices, unit costs, demand and capacity. Budgeted sales revenue and cash collections differ where customers buy on credit.","A simple business plan explains the product or service, customers, evidence of demand, competitors, operations, staffing, startup assets, finance, budgets, cash forecasts and risks. For a poultry or craft project, connect quantities and costs to realistic capacity. Show how records will be kept and how performance will be checked against budgets. A sensible plan explains what happens if sales are lower or input costs rise rather than promising guaranteed returns.","Complete a three-month sales and production budget. Sales targets are January 200, February 250 and March 300 units at $150 each, giving revenue $30,000, $37,500 and $45,000. Opening finished goods in January are 30 units and desired closing stocks are 50, 60 and 70. Production is January 200 + 50 − 30 = 220 units; February 250 + 60 − 50 = 260; March 300 + 70 − 60 = 310. Total production 790 equals total sales 750 + final inventory 70 − initial inventory 30.","Connect production to its inputs. If each finished unit uses 2 kg of material at $20 per kg and one labour hour at $30, material usage costs per unit are $40 and direct labour $30. For the 220, 260 and 310 production units, material usage is 440, 520 and 620 kg, costing $8,800, $10,400 and $12,400; direct labour costs $6,600, $7,800 and $9,300. Add only the overhead basis specified. Material purchases differ from usage when raw-material stocks change.","A short craft-business plan should make the numbers tell one consistent story. State the product, target customers, evidence of expected demand, monthly units, selling price, materials, labour, equipment, suppliers and capacity. Then give startup finance, a sales/production budget and a cash forecast with collection and payment assumptions. Explain who records transactions and how cash and inventory are checked. If the plan forecasts 310 units but capacity is 250, change capacity or the sales plan rather than leaving incompatible promises.","Stress-test one assumption and explain an action. If budgeted monthly sales of 300 units fall 20%, sales become 240 and revenue at $150 falls from $45,000 to $36,000. Cash receipts may fall in a later month when sales are on credit. Recalculate production, input purchases and the cash forecast using the inventory policy; avoid automatically cutting costs that are fixed. Specify a feasible response, such as reducing the next purchase order or arranging finance before a shortfall."]},{"title":"Worked example","paragraphs":["January sales target 200 units at $150 gives revenue $30,000. Opening finished goods 30 units and desired closing 50 require production 200 + 50 − 30 = 220 units. If each uses 2 kg of material, production needs 440 kg. With opening raw materials 40 kg and desired closing 60 kg, buy 440 + 60 − 40 = 460 kg."]},{"title":"Common mistake","paragraphs":["A production budget counts units to make; a cash budget counts money expected to move. Do not mix the columns."]}],"keyPoints":["Production = sales + desired closing finished goods − opening finished goods.","Material purchases must cover production needs and the planned inventory change.","Check capacity, cash requirements and the evidence behind the forecast."],"summary":"Link sales, production and material requirements so the business plan rests on consistent figures. Explain assumptions and test how changed demand or costs affect the plan.","check":{"question":"Sales budget 500 units, opening inventory 80, target closing 100. Production required?","answer":"500 + 100 − 80 = 520 units."},"flashcards":[{"front":"Sales budget 500 units, opening inventory 80, target closing 100. Production required?","back":"500 + 100 − 80 = 520 units."},{"front":"What mistake should you avoid when studying sales budgets, production budgets and a business plan?","back":"A production budget counts units to make; a cash budget counts money expected to move. Do not mix the columns."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status,expected_total_marks) values ('principles-of-accounts','poa-original-criteria-v1','POA-ORIGINAL-02-01','[{"id":"POA-Q1::1","maxMarks":1,"kind":"numeric","expected":116000,"tolerance":0.005,"acceptedPhrases":[],"sourcePartId":"POA-Q1::1","sourceFormat":"poa-original-paper2","sourceMarking":{"answer":116000,"solution":"120,000 − 4,000","objectiveCode":"S5.3","criteria":[{"code":"B1","marks":1,"depends":[],"field":"answer","check":{"type":"numeric","value":116000,"tolerance":0.005}}]}},{"id":"POA-Q1::2","maxMarks":1,"kind":"numeric","expected":68000,"tolerance":0.005,"acceptedPhrases":[],"sourcePartId":"POA-Q1::2","sourceFormat":"poa-original-paper2","sourceMarking":{"answer":68000,"solution":"70,000 − 2,000","objectiveCode":"S5.3","criteria":[{"code":"B1","marks":1,"depends":[],"field":"answer","check":{"type":"numeric","value":68000,"tolerance":0.005}}]}},{"id":"POA-Q1::3","maxMarks":1,"kind":"numeric","expected":86000,"tolerance":0.005,"acceptedPhrases":[],"sourcePartId":"POA-Q1::3","sourceFormat":"poa-original-paper2","sourceMarking":{"answer":86000,"solution":"15,000 + 68,000 + 3,000","objectiveCode":"S5.3","criteria":[{"code":"B1","marks":1,"depends":[],"field":"answer","check":{"type":"numeric","value":86000,"tolerance":0.005}}]}},{"id":"POA-Q1::4","maxMarks":1,"kind":"numeric","expected":68000,"tolerance":0.005,"acceptedPhrases":[],"sourcePartId":"POA-Q1::4","sourceFormat":"poa-original-paper2","sourceMarking":{"answer":68000,"solution":"86,000 − 18,000","objectiveCode":"S5.3","criteria":[{"code":"B1","marks":1,"depends":[],"field":"answer","check":{"type":"numeric","value":68000,"tolerance":0.005}}]}},{"id":"POA-Q1::5","maxMarks":1,"kind":"numeric","expected":48000,"tolerance":0.005,"acceptedPhrases":[],"sourcePartId":"POA-Q1::5","sourceFormat":"poa-original-paper2","sourceMarking":{"answer":48000,"solution":"116,000 − 68,000","objectiveCode":"S5